insert into activities (id, name, type, tags, ages, cost, location, km, season, duration, description, url, rating, notes, conditions, lat, lng, daypart, added_by, verified) values
  (1, 'Jan Juc Skatepark', 'skatepark', '{"kids-friendly","free","outdoor","local-knowledge"}', '{"kids","teens","adults"}', 'Free', 'Jan Juc', 0, '{"any"}', '< 1hr / half-day', 'Solid street course right in the neighbourhood. Good for beginners and intermediates. Quiet on weekday mornings.', 'https://www.google.com/maps?q=-38.3657,144.2979', 5, 'Lights on till late', '{"dry-ground"}', -38.3657, 144.2979, 'day', 'Family', true),
  (2, 'Bells Beach', 'beach', '{"iconic","surf-watching","walking","free"}', '{"all-ages"}', 'Free', 'Bells Beach / Torquay', 3, '{"summer","autumn","spring"}', '< 1hr – half-day', 'World-famous surf break. Great for watching pros rip during Rip Curl Pro. Rock pools at low tide. Bring shoes for rocks.', 'https://www.google.com/maps?q=-38.3721,144.2829', 5, 'Parking fills early on big swell days', '{"low-tide","calm-sea"}', -38.3721, 144.2829, 'day', 'Family', true),
  (3, 'Point Addis Marine Park', 'beach', '{"snorkelling","nudist-optional","swimming","scenic"}', '{"teens","adults"}', 'Free', 'Anglesea', 8, '{"summer","spring"}', 'half-day', 'Hidden gem. Walk down to secluded Addiscot Beach. Incredible snorkelling on calm days. Koalas in the scrub on the way.', 'https://www.google.com/maps?q=-38.3975,144.2534', 5, 'Steep walk back up', '{"low-tide","calm-sea"}', -38.3975, 144.2534, 'day', 'Family', true),
  (4, 'Surf Coast Walk – Jan Juc to Torquay', 'walk', '{"coastal","scenic","dogs-welcome","free"}', '{"all-ages"}', 'Free', 'Jan Juc → Torquay', 0, '{"any"}', '< 1hr – half-day', 'Beautiful cliff-top walk. Flat and easy. Stunning ocean views. End at Torquay Surf Beach for a swim or café stop.', 'https://www.google.com/maps?q=-38.356,144.3082', 5, 'Dog-friendly the whole way', '{"dry-trails","low-wind"}', -38.356, 144.3082, 'day', 'Family', true),
  (5, 'Torquay Skatepark – Beach Rd (near surf shops)', 'skatepark', '{"large","lit","kids-friendly","free"}', '{"kids","teens","adults"}', 'Free', 'Torquay', 4, '{"any"}', '< 1hr – half-day', 'The original Torquay concrete skatepark on Beach Rd, right near the surf shops. Double bowl with a spine separating two sections — one side deeper than the other. Classic old-school park, still punches above its weight. Great location — walk to surf shops, cafes, and Front Beach after your session.', 'https://www.google.com/maps?q=-38.3374,144.3278', 5, '81 Beach Rd, Torquay. Near DC Store.', '{"dry-ground"}', -38.3374, 144.3278, 'day', 'Family', true),
  (6, 'Anglesea Bike Trail', 'bike track', '{"family-friendly","flat","river","scenic"}', '{"all-ages"}', 'Free', 'Anglesea', 15, '{"spring","summer","autumn"}', 'half-day', 'Lovely flat trail along the Anglesea River. Perfect for little kids on bikes. Links to the main beach and town.', 'https://www.google.com/maps?q=-38.4056,144.1824', 4, 'Hire bikes available nearby', '{"dry-trails"}', -38.4056, 144.1824, 'day', 'Family', true),
  (7, 'Lorne Cascades Walk', 'walk', '{"waterfall","rainforest","swimming hole"}', '{"all-ages"}', 'Free', 'Lorne', 30, '{"spring","summer"}', 'half-day', 'Magical rainforest walk to a waterfall and swimming hole. Some steps but totally worth it. Cold water!', 'https://www.google.com/maps?q=-38.5423,143.9908', 5, 'Slippery after rain — wear grip shoes', '{"dry-trails","warm"}', -38.5423, 143.9908, 'day', 'Family', true),
  (9, 'Fairhaven Beach', 'beach', '{"swimming","surf","local-favourite","walking"}', '{"all-ages"}', 'Free', 'Fairhaven', 6, '{"summer","spring"}', '< 1hr – half-day', 'Less crowded than Torquay beaches. Patrolled in summer. Long stretch of sand great for walking.', 'https://www.google.com/maps?q=-38.4953,144.0399', 4, null, '{"calm-sea","warm"}', -38.4953, 144.0399, 'day', 'Family', true),
  (10, 'Torquay Surf Academy – Lesson', 'surf', '{"surfing","lessons","beginners","kids"}', '{"kids","teens","adults"}', 'Moderate', 'Torquay', 4, '{"summer","spring","autumn"}', 'half-day', 'Group lessons for beginners. Kids love it. All gear provided. Book ahead in summer.', 'https://www.torquaysurfacademy.com.au', 5, 'Book 2 weeks ahead in Jan/Feb', '{"calm-sea","warm"}', -38.335, 144.327, 'day', 'Family', true),
  (11, 'Karaoke Night at Home', 'at-home', '{"rainy-day","music","family","free"}', '{"all-ages"}', 'Free', 'Home', 0, '{"any"}', 'half-day – full-day', 'Set up YouTube karaoke, make a playlist of everyone''s faves. Scoring system makes it competitive and hilarious.', 'https://www.youtube.com/results?search_query=karaoke', 5, 'Use a Bluetooth mic for extra drama', '{"good-in-rain"}', -38.3655, 144.2978, 'both', 'Family', true),
  (12, 'Backyard Camping', 'at-home', '{"overnight","stars","free","adventure"}', '{"kids","teens"}', 'Free', 'Home / Backyard', 0, '{"summer","autumn","spring"}', 'full-day', 'Pitch the tent in the backyard. Campfire (if allowed), toasted marshmallows, morning pancakes. Epic for kids.', null, 5, 'Check fire restrictions first', '{"clear-sky","warm","no-fire-ban"}', -38.3655, 144.2978, 'both', 'Family', true),
  (13, 'Movie Marathon – Theme Night', 'at-home', '{"rainy-day","movies","cosy","free"}', '{"all-ages"}', 'Free', 'Home', 0, '{"winter","any"}', 'half-day – full-day', 'Pick a theme (e.g. Pixar, Harry Potter, 80s action). Make themed snacks. Vote on films. Build a fort.', null, 5, 'Great for rainy winter weekends', '{"good-in-rain"}', -38.3655, 144.2978, 'both', 'Family', true),
  (14, 'Anglesea Golf Course (Kangaroos!)', 'nature', '{"golf","wildlife","scenic","unique"}', '{"teens","adults"}', 'Cheap', 'Anglesea', 15, '{"any"}', 'half-day', 'Kangaroos literally live on the fairways. Hire clubs. Beginners welcome. One of the most unique courses in Aus.', 'https://www.angleseagolfclub.com.au', 5, 'Kangaroos at dawn are incredible', '{"dry-trails"}', -38.4049, 144.1782, 'day', 'Family', true),
  (15, 'Airey''s Inlet Lighthouse Walk', 'walk', '{"lighthouse","coastal","history","scenic"}', '{"all-ages"}', 'Free', 'Airey''s Inlet', 18, '{"any"}', '< 1hr – half-day', 'Short walk to Split Point Lighthouse (the one from Round the Twist!). Great views. Free to walk up to the base.', 'https://www.google.com/maps?q=-38.4607,144.1032', 4, 'Tours of the lighthouse available', '{"dry-ground"}', -38.4607, 144.1032, 'day', 'Family', true),
  (16, 'Surf Coast MTB Trails – Ironbark Basin', 'bike track', '{"mountain biking","trails","intermediate"}', '{"teens","adults"}', 'Free', 'Anglesea', 15, '{"any"}', 'half-day – full-day', 'Brilliant network of MTB trails through the bush. Mix of easy and challenging. Great flow trails.', 'https://trailsplus.com.au/ironbark-basin', 5, 'Hire bikes in Anglesea', '{"dry-trails"}', -38.3893, 144.2314, 'day', 'Family', true),
  (17, 'Board Game Evening', 'at-home', '{"rainy-day","strategy","family","free"}', '{"all-ages"}', 'Free', 'Home', 0, '{"any"}', '< 1hr – half-day', 'Break out Catan, Ticket to Ride, Codenames, or Uno. Make it a regular thing. Great for when screens feel like too much.', null, 5, 'Invite the neighbours', '{"good-in-rain"}', -38.3655, 144.2978, 'both', 'Family', true),
  (18, 'Jan Juc Rockpools', 'beach', '{"rockpools","marine","free","educational"}', '{"toddler","kids"}', 'Free', 'Jan Juc', 1, '{"low tide","any"}', '< 1hr', 'Just down the path from the skatepark. Check the tide chart first. Crabs, starfish, anemones. Perfect for little ones.', 'https://www.google.com/maps?q=-38.3682,144.296', 5, 'Best at low tide — check Willyweather', '{"low-tide"}', -38.3682, 144.296, 'day', 'Family', true),
  (19, 'Torquay Library – Kids Programs', 'community', '{"library","reading","free","kids"}', '{"toddler","kids"}', 'Free', 'Torquay', 4, '{"any"}', '< 1hr', 'Story time, holiday programs, maker space. Fantastic free resource. Check their program calendar.', 'https://www.surfcoast.vic.gov.au/library', 4, 'Holiday programs book out fast', '{"good-in-rain"}', -38.3328, 144.325, 'day', 'Family', true),
  (20, 'Cook a New Recipe Together', 'at-home', '{"cooking","creative","learning","family"}', '{"all-ages"}', 'Cheap', 'Home', 0, '{"any"}', '< 1hr – half-day', 'Pick a cuisine nobody has tried. Everyone gets a job — chopper, stirrer, taster. Messy and memorable.', null, 5, 'Great for a slow Sunday', '{"good-in-rain"}', -38.3655, 144.2978, 'both', 'Family', true),
  (21, 'Torquay Beach – Front Beach', 'beach', '{"swimming","patrolled","central","family"}', '{"all-ages"}', 'Free', 'Torquay', 4, '{"summer","spring"}', '< 1hr – half-day', 'Patrolled beach right in Torquay town. Calm bay side great for young swimmers. Cafes and shops steps away.', 'https://www.google.com/maps?q=-38.3269,144.3252', 4, 'Gets very crowded in Jan/Feb', '{"calm-sea","warm"}', -38.3269, 144.3252, 'day', 'Family', true),
  (22, 'Scavenger Hunt – Neighbourhood', 'at-home', '{"outdoor","free","kids","creative"}', '{"toddler","kids","teens"}', 'Free', 'Jan Juc / surrounds', 0, '{"any"}', '< 1hr', 'Write your own list — natural items, textures, colours, street art, bird species. App-based ones (Geocaching) are fun too.', 'https://www.geocaching.com', 5, 'Make it harder for older kids', '{"dry-ground"}', -38.3655, 144.2978, 'both', 'Family', true),
  (23, 'Surf World Museum', 'museum', '{"surfing","history","culture","local"}', '{"all-ages"}', 'Cheap', 'Torquay', 4, '{"any"}', '< 1hr', 'Small but brilliant museum on surf culture and history. Perfect for a rainy day. Great for visitors too.', 'https://www.surfworld.com.au', 4, null, '{"good-in-rain"}', -38.3381, 144.3258, 'day', 'Family', true),
  (24, 'Lorne Beach & Pier', 'beach', '{"pier","swimming","fishing","scenic"}', '{"all-ages"}', 'Free', 'Lorne', 30, '{"summer","spring","autumn"}', 'half-day', 'Beautiful protected beach with a classic old pier. Great swimming. Lorne town is lovely for lunch or coffee.', 'https://www.google.com/maps?q=-38.54,143.9786', 5, '90 min round trip from Jan Juc', '{"calm-sea","warm"}', -38.54, 143.9786, 'day', 'Family', true),
  (25, 'Backyard Sports Day', 'at-home', '{"outdoor","active","free","competitive"}', '{"all-ages"}', 'Free', 'Home', 0, '{"spring","summer","autumn"}', '< 1hr – half-day', 'Set up stations: egg-and-spoon, sprints, hula hoop, target throw. Invite neighbours for a community sports day.', null, 5, 'Ribbon prizes from the $2 shop!', '{"warm"}', -38.3655, 144.2978, 'both', 'Family', true),
  (28, 'Swell Café', 'cafe', '{"local-favourite","brunch","kids-friendly","dogs-welcome"}', '{"all-ages"}', 'Cheap', 'Jan Juc', 1, '{"any"}', '< 1hr', 'The Jan Juc locals'' café. All-day brunch and lunch, fresh juices, smoothies. Indoor and outdoor seating. Surfers, families, dogs — everyone welcome. Rarely a spare table on weekends.', 'https://www.google.com/maps?q=-38.3661,144.2984', 5, '2 Stuart Ave, Jan Juc. Gets packed — go early or late', '{"any-weather"}', -38.3661, 144.2984, 'both', 'Research', true),
  (29, 'Pond Café', 'cafe', '{"ocean-views","specialty-coffee","brunch","esplanade"}', '{"adults","teens"}', 'Cheap', 'Torquay', 4, '{"any"}', '< 1hr', 'On the Torquay esplanade with views across the grass to the sea. Grinding Seven Seeds, interesting breakfast menu. One of the original specialty coffee spots in town. Sophisticated vibe.', 'https://www.google.com/maps?q=-38.3281,144.3253', 4, '39 The Esplanade, Torquay', '{"any-weather"}', -38.3281, 144.3253, 'both', 'Research', true),
  (30, 'Mavis Mavis', 'cafe', '{"earthy","quick","popular","surf-vibe"}', '{"all-ages"}', 'Cheap', 'Torquay', 4, '{"any"}', '< 1hr', 'Earthy beach vibe, surf photos on the walls, always a queue but they move fast. Great coffee. Central Torquay. Good quick stop before hitting the beach.', 'https://www.google.com/maps?q=-38.3343,144.3276', 4, 'Torquay main street', '{"any-weather"}', -38.3343, 144.3276, 'both', 'Research', true),
  (31, 'Maple Bakery & Café', 'cafe', '{"canadian-bakery","bagels","donuts","unique","family"}', '{"all-ages"}', 'Cheap', 'Torquay', 4, '{"any"}', '< 1hr', 'Authentic Canadian-inspired bakery — bagels, cronuts, donuts, pastries. Try the Beaver''s Tails. Locals say it''s some of the best coffee in town. Behind Bunnings. Indoor and outdoor seating.', 'https://www.google.com/maps?q=-38.3277,144.3249', 5, 'Behind Bunnings, Torquay. Kids love the donuts', '{"any-weather"}', -38.3277, 144.3249, 'both', 'Research', true),
  (32, 'Blackman''s Brewery', 'cafe', '{"craft-beer","family-friendly","beer-garden","fire","community"}', '{"teens","adults"}', 'Moderate', 'Torquay', 4, '{"any"}', '< 1hr – half-day', 'One of Victoria''s top brewpubs. 8 beers brewed on-site, tasting paddles available. Huge beer garden for sunny days, roaring open fire for winter. Family-friendly, great food.', 'https://blackmansbrewery.com.au', 5, 'Great for a long lazy lunch', '{"any-weather"}', -38.329, 144.3245, 'both', 'Research', true),
  (33, 'Anglesea Paddleboards & Canoe Hire', 'water', '{"paddleboarding","kayaking","river","family","kids"}', '{"all-ages"}', 'Moderate', 'Anglesea', 15, '{"spring","summer","autumn"}', 'half-day', 'Kayaks, paddleboats, canoes and Giant SUP on the beautiful Anglesea River. All equipment and safety gear included. Great for kids. Calm, sheltered water — perfect for beginners.', 'https://www.google.com/maps?q=-38.4062,144.184', 4, 'Cnr River Reserve Rd / Noble St, Anglesea', '{"calm-sea","warm"}', -38.4062, 144.184, 'day', 'Research', true),
  (34, 'Jumpz Anglesea', 'sport', '{"amusement","kids","family","river","fun"}', '{"toddler","kids","teens"}', 'Moderate', 'Anglesea', 15, '{"spring","summer"}', '< 1hr – half-day', 'Amusement park on the Anglesea river mouth — trampolines, inflatables, water activities. Kids absolutely love it. Right next to the paddleboat hire so you can combine both.', 'https://www.google.com/maps?q=-38.4041,144.1807', 4, '105 Great Ocean Rd, Anglesea', '{"warm"}', -38.4041, 144.1807, 'day', 'Research', true),
  (35, 'Surf Coast Strawberry Fields', 'cafe', '{"berry-picking","farm","family","seasonal","food"}', '{"toddler","kids","teens"}', 'Cheap', 'Mt Duneed', 12, '{"summer","autumn"}', '< 1hr', 'Pick your own strawberries at this working farm just north of Torquay. Kids pick 250g for $3, adults double that for $7. Seasonal — check ahead. Beautiful setting on the Surf Coast Hwy.', 'https://www.google.com/maps?q=-38.2385,144.3196', 4, 'Mccan''s Rd, Surf Coast Hwy, Mt Duneed', '{"dry-ground","warm"}', -38.2385, 144.3196, 'both', 'Research', true),
  (36, 'Great Ocean Road Chocolaterie', 'cafe', '{"chocolate","family","food","unique","rainy-day"}', '{"all-ages"}', 'Cheap', 'Bellbrae', 10, '{"any"}', '< 1hr – half-day', 'Watch chocolatiers at work through the glass, sample chocolate and ice cream. Special events calendar runs month-long themed celebrations — hot chocolate, rocky road, brownies. Great rainy day activity.', 'https://www.gorchocolaterie.com.au', 4, '1200 Great Ocean Rd, Bellbrae', '{"good-in-rain"}', -38.3693, 144.2445, 'both', 'Research', true),
  (37, 'Anglesea Bike Park – Camp Rd (4X / Jumps)', 'bike track', '{"MTB","all-levels","family","purpose-built","free"}', '{"kids","teens","adults"}', 'Free', 'Anglesea', 15, '{"any"}', 'half-day – full-day', 'Purpose-built skills park near Anglesea town. Designed by legendary trail builder Glen Jacobs. Features a 4X downhill track, two jump lines, short XC loop and trials section. Great for kids and all ages. Central location — ride here from town. Note: Ironbark Spur is a longer trail further into the network.', 'https://trailsplus.com.au/ironbark-basin', 5, 'Check Trailforks for trail conditions before going', '{"dry-trails"}', -38.3893, 144.2314, 'day', 'Research', true),
  (38, 'Forrest MTB Trails – Southern Network', 'bike track', '{"MTB","world-class","all-levels","pump-track","flow-trails"}', '{"kids","teens","adults"}', 'Free', 'Forrest', 75, '{"any"}', 'full-day', 'One of Australia''s top MTB destinations. 100km of singletrack across 36 trails. Southern network (recently upgraded 2023) has pump tracks, jump lines, flow trails and adaptive tracks. Flagship trail: Red Carpet — 4.5km mostly descending with 216m vertical drop. Great for families and experts alike.', 'https://www.exploreoutdoors.vic.gov.au/activities/mountain-biking/forrest-mountain-bike-trails', 5, 'Bike hire available in town. Stay overnight to do both networks. Forrest Brewing Co for post-ride beers!', '{"dry-trails"}', -38.5238, 143.7259, 'day', 'Research', true),
  (39, 'Forrest MTB Trails – Yaugher Network', 'bike track', '{"MTB","singletrack","technical","handbuilt","classic"}', '{"teens","adults"}', 'Free', 'Forrest', 75, '{"any"}', 'full-day', 'The original handbuilt Forrest network north of town — skinny, natural singletrack through lush forest. Highlights: Marriner''s Run (rock rollovers, fast descents, bermed gullies), Grasstrees (black diamond challenges), Yaugher Superloop. Access via Tiger Rail Trail from town.', 'https://trailsplus.com.au/forrest', 5, 'Check Ride Forrest website/app for trail conditions. Can be muddy in winter.', '{"dry-trails"}', -38.5238, 143.7259, 'day', 'Research', true),
  (40, 'You Yangs MTB Park – Kurrajong', 'bike track', '{"MTB","beginner-friendly","family","flat","granite"}', '{"kids","teens","adults"}', 'Free', 'You Yangs', 45, '{"any"}', 'half-day', 'Beginner to intermediate MTB in the iconic You Yangs granite peaks. Kurrajong section is mostly flat with boardwalks, dry creek crossings and fun features. Perfect introduction to MTB for kids and new riders. 50km+ of trails across the whole park.', 'https://www.parks.vic.gov.au/places-to-see/parks/you-yangs-regional-park', 4, 'Kurrajong Ave car park. Free entry. Koalas often spotted in trees!', '{"dry-trails"}', -37.9249, 144.458, 'day', 'Research', true),
  (41, 'You Yangs MTB Park – Stockyards', 'bike track', '{"MTB","advanced","granite","technical","downhill"}', '{"teens","adults"}', 'Free', 'You Yangs', 45, '{"any"}', 'half-day – full-day', 'The advanced northern section of You Yangs. Set around a giant quarry bowl with granite tors. Features include rock gardens, berms, natural ramps, jumps and dedicated downhill runs. 14 trails from easy to extremely difficult. Best MTB near Geelong/Melbourne.', 'https://www.visitmelbourne.com/regions/melbourne/see-and-do/outdoor-and-adventure/cycling/you-yangs-mountain-bike-park', 5, 'Drysdale Rd car park for Stockyards. Dusty in summer — best in autumn/winter', '{"dry-trails"}', -37.9192, 144.4614, 'day', 'Research', true),
  (42, 'Lorne & Otways MTB / Gravel Trails', 'bike track', '{"MTB","gravel","rainforest","remote","scenic","advanced"}', '{"teens","adults"}', 'Free', 'Lorne', 30, '{"spring","autumn"}', 'half-day – full-day', '40 trails mapped around Lorne on Trailforks. Mix of MTB singletrack, gravel and fire roads through Great Otway National Park. Sharps Track descent into Lorne is a classic. Also links to Erskine Falls Rd and Distillery Creek area. Stunning rainforest riding.', 'https://www.trailforks.com/region/lorne/', 4, 'Check Trailforks for current trail status. Can be very muddy in winter.', '{"dry-trails"}', -38.5238, 143.7259, 'day', 'Research', true),
  (43, 'Old Beechy Rail Trail', 'bike track', '{"rail-trail","gravel","scenic","family","otways"}', '{"all-ages"}', 'Free', 'Birregurra / Otways', 60, '{"spring","autumn","summer"}', 'full-day', 'The Otways'' most famous rail trail — converted railway line through lush farmland and forest. Relatively flat and accessible. Connects to Forrest. Can be ridden as a day trip or overnighter. Stunning scenery, local produce stops along the way.', 'https://www.adventurecyclingvictoria.com/rides/otways-old-beechy-turtons-track', 4, 'Check for any section closures before going. Gravel bike recommended.', '{"dry-trails"}', -38.4773, 143.8479, 'day', 'Research', true),
  (44, 'Anglesea MTB – Hurst Rd / Eumeralla Network', 'bike track', '{"MTB","XC","singletrack","all-levels","free","coastal-bush"}', '{"kids","teens","adults"}', 'Free', 'Anglesea', 15, '{"any"}', 'half-day – full-day', 'The main sanctioned XC singletrack network in Anglesea — ~30km of trails through Great Otway National Park. Bounded by Great Ocean Rd, Hurst Rd and the Eumeralla Scout Camp. Green and blue trails, sandy and undulating near Hurst Rd, steeper on the far side. Fun jumps and rollovers throughout. SEPARATE to the Bike Park on Camp Rd. Park at Hurst Rd trailhead off the Great Ocean Rd.', 'https://www.surfcoastmtb.com.au/trails/', 4, 'Park at Hurst Rd trailhead. Get the Trailforks app for navigation — signage not complete yet.', '{"dry-trails"}', -38.4203, 144.1578, 'day', 'Research', true),
  (45, 'Anglesea Skatepark', 'skatepark', '{"free","outdoor","all-levels","kids-friendly","coastal"}', '{"kids","teens","adults"}', 'Free', 'Anglesea', 15, '{"any"}', '< 1hr', 'Concrete skatepark at Lions Park right on the Great Ocean Road in Anglesea. Good size for a small town — fun for all levels. Combine with a swim at Anglesea Beach right next door.', 'https://www.google.com/maps?q=-38.4044,144.1829', 4, 'Lions Park, Great Ocean Rd, Anglesea', '{"dry-ground"}', -38.4044, 144.1829, 'day', 'Research', true),
  (46, 'Aireys Inlet Skatepark', 'skatepark', '{"free","bowl","small","quiet","holiday"}', '{"kids","teens"}', 'Free', 'Aireys Inlet', 18, '{"any"}', '< 1hr', 'Compact skatepark with a 4ft figure-8 peanut bowl, mellow spine and quarter pipes. Revamped with extensions adding rails and box ledges. Fun little park — great if you''re staying in the area. Quiet and relaxed vibe. 28 Inlet Crescent.', 'https://www.google.com/maps?q=-38.4594,144.1023', 3, '28 Inlet Cres, Aireys Inlet. Small but fun — good for learners', '{"dry-ground"}', -38.4594, 144.1023, 'day', 'Research', true),
  (47, 'Lorne Skatepark (Kay Langan)', 'skatepark', '{"free","bowl","street","benchmark","family"}', '{"kids","teens","adults"}', 'Free', 'Lorne', 30, '{"any"}', '< 1hr', 'The benchmark skatepark on the Great Ocean Road — still the best one along the coast. Large concrete bowl plus a decent street section with banks, rails, ledges and hips. Right near the beach and playground at Mountjoy Parade. Opened 2005, Lions Club supported. Beautiful spot — family can picnic while kids skate.', 'https://www.google.com/maps?q=-38.5399,143.9773', 5, '84 Mountjoy Parade, Lorne. Next to the beach and playground — perfect family stop', '{"dry-ground"}', -38.5399, 143.9773, 'day', 'Research', true),
  (48, 'Connewarre Skatepark', 'skatepark', '{"free","small","quiet","local","hidden-gem"}', '{"kids","teens"}', 'Free', 'Connewarre', 20, '{"any"}', '< 1hr', 'Small but charming concrete skatepark in Connewarre Reserve, next to the tennis courts behind the Fire Brigade. 3ft quarter at one end, bank on the other, central feature obstacle. Perfect for young kids learning. Very quiet — rarely crowded.', 'https://www.google.com/maps?q=-38.2315,144.3804', 3, 'Connewarre Reserve, behind the Fire Brigade', '{"dry-ground"}', -38.2315, 144.3804, 'day', 'Research', true),
  (49, 'Moriac Skatepark', 'skatepark', '{"free","quiet","country","local-knowledge","hidden-gem"}', '{"kids","teens"}', 'Free', 'Moriac', 20, '{"any"}', '< 1hr', 'Small country skatepark in Moriac — a hidden gem that most people don''t know about. Quiet and never crowded. Good for a quick session if you''re passing through.', 'https://www.google.com/maps?q=-38.284,144.3031', 3, '830 Hendy Main Rd, Moriac', '{"dry-ground"}', -38.284, 144.3031, 'day', 'Research', true),
  (50, 'Geelong Waterfront Skatepark', 'skatepark', '{"free","large","waterfront","all-levels","iconic"}', '{"kids","teens","adults"}', 'Free', 'Geelong', 35, '{"any"}', '< 1hr – half-day', 'Great concrete skatepark right on the Geelong waterfront at Western Beach. Larger than the surf coast parks — worth the drive for a big session. Combine with the Geelong waterfront precinct: carousel, playground, cafes, waterfront walk. Great day trip destination.', 'https://www.google.com/maps?q=-38.1477,144.3616', 4, 'Western Beach, Geelong waterfront. Combine with a walk and lunch on the waterfront', '{"dry-ground"}', -38.1477, 144.3616, 'day', 'Research', true),
  (51, 'Torquay North Skatepark – Bowl (Merrijig Dr)', 'skatepark', '{"bowl","12ft","pool-coping","advanced","free"}', '{"teens","adults"}', 'Free', 'Torquay North', 5, '{"any"}', '< 1hr', 'Torquay''s newer, larger skatepark — a massive 12ft bowl with pool coping. Three sections: the shallower two-thirds at 7ft, deep end at 12ft. Super intimidating deep end, but the shallower section is great for progressing. Wide open street area with gentle banks for beginners too. Different vibe to the Beach Rd park.', 'https://www.google.com/maps?q=-38.3168,144.3238', 5, '2 Merrijig Drive, Torquay. The big bowl — worth the drive from Jan Juc', '{"dry-ground"}', -38.3168, 144.3238, 'day', 'Research', true),
  (52, 'Waurn Ponds Skatepark', 'skatepark', '{"vert","street","upgraded","all-levels","geelong"}', '{"kids","teens","adults"}', 'Free', 'Waurn Ponds / Geelong', 35, '{"any"}', '< 1hr – half-day', '$2M upgrade transformed this legendary park into one of the best in the region. Everything from vert to street — bowls, vert ramp, street obstacles, transitions. Been a Geelong institution for decades, now better than ever. Local skaters rave about the transformation.', 'https://www.google.com/maps?q=-38.2116,144.3027', 5, '173-199 Pioneer Rd, Grovedale. Recently upgraded — don''t judge it by old photos', '{"dry-ground"}', -38.2116, 144.3027, 'day', 'Research', true),
  (53, 'Armstrong Creek Skatepark', 'skatepark', '{"new","street","family-friendly","close-to-torquay"}', '{"kids","teens","adults"}', 'Free', 'Armstrong Creek / Mt Duneed', 20, '{"any"}', '< 1hr', 'Newer skatepark on Unity Drive in Mt Duneed — only a few minutes from Geelong, and closer to Torquay than most Geelong parks. Good street section, clean concrete. Great option if you''re heading towards Geelong.', 'https://www.google.com/maps?q=-38.2295,144.3207', 3, 'Unity Drive, Mt Duneed. Close to Torquay — easy detour', '{"dry-ground"}', -38.2295, 144.3207, 'day', 'Research', true),
  (54, 'Ocean Grove Skatepark (Ocean Grove Bowl)', 'skatepark', '{"bowl","free","bellarine","all-levels"}', '{"kids","teens","adults"}', 'Free', 'Ocean Grove', 40, '{"any"}', '< 1hr', 'Great concrete bowl on Shell Road Reserve next to the Bellarine Aquatic & Sports Centre. Snakes from a 5ft section into a deeper 8ft section — satisfying lines to link. Good day out combined with Ocean Grove beach or a swim at the aquatic centre next door.', 'https://www.google.com/maps?q=-38.266,144.5168', 4, 'Shell Rd Reserve, Ocean Grove. Next to the aquatic centre', '{"dry-ground"}', -38.266, 144.5168, 'day', 'Research', true),
  (55, 'Barwon Heads Skatepark', 'skatepark', '{"bowl","9ft","convic","bellarine","coastal"}', '{"teens","adults"}', 'Free', 'Barwon Heads', 40, '{"any"}', '< 1hr', 'Beautifully designed Convic-built park in the Barwon Heads Community Park. Unique dog bone-shaped bowl — 9ft deep end tapering to a 4ft shallow section. Great for transition skating. Relaxed coastal town vibe. Combine with a walk to the Barwon Heads bluff for stunning views.', 'https://www.google.com/maps?q=-38.2773,144.4927', 4, 'Sheepwash Rd, Barwon Heads. Nice chill spot after a session', '{"dry-ground"}', -38.2773, 144.4927, 'day', 'Research', true),
  (56, 'Leopold Skatepark', 'skatepark', '{"mini-ramp","street","local-favourite","all-levels"}', '{"kids","teens","adults"}', 'Free', 'Leopold / Geelong', 35, '{"any"}', '< 1hr', 'Small park but packs a punch — widely regarded as one of the best mini ramps in the Geelong region. 4ft mini ramp tapering to banks, plus an extended street section with stairs, rails, ledges and boxes. Friendly community of local skaters. Great for learning lip tricks.', 'https://www.google.com/maps?q=-38.1748,144.4638', 4, 'Cnr Bellarine Hwy & Melaluka Rd, Leopold', '{"dry-ground"}', -38.1748, 144.4638, 'day', 'Research', true),
  (57, 'Lara Skatepark', 'skatepark', '{"snake-run","bowl","new","well-designed","geelong"}', '{"kids","teens","adults"}', 'Free', 'Lara', 40, '{"any"}', '< 1hr', 'One of Victoria''s best designed skateparks — opened 2017. Epic snake-run concrete bowl (6ft down to 4ft) plus a solid street section. Great flow and well-maintained. Worth a detour on the way to/from Melbourne.', 'https://www.google.com/maps?q=-38.0189,144.4053', 4, 'Lara township. On the way to Melbourne — great road trip stop', '{"dry-ground"}', -38.0189, 144.4053, 'day', 'Research', true),
  (58, 'Corio Skatepark (Stead Park Bowls)', 'skatepark', '{"bowl","free","beginner-friendly","geelong-north"}', '{"kids","teens"}', 'Free', 'Corio / Geelong North', 38, '{"any"}', '< 1hr', 'Three concrete bowls of different shapes and sizes — no coping, mellow and forgiving. Super welcoming for younger kids and beginners. Paint-tray dish, oblong bowl, and a larger open bowl. Good first-bowl experience for kids.', 'https://www.google.com/maps?q=-38.1166,144.3454', 3, 'Stead Park, Anakie Rd, Corio. Best for young beginners', '{"dry-ground"}', -38.1166, 144.3454, 'day', 'Research', true),
  (59, 'Djila Tjarra Skatepark (North Shore / Norlane)', 'skatepark', '{"deep-bowl","advanced","geelong","two-parks-linked"}', '{"teens","adults"}', 'Free', 'Norlane / Geelong North', 38, '{"any"}', '< 1hr', 'Two skateparks linked together — old and new park connected so you can skate between them. Features a deep bowl that local pros rate as one of the best in the region. Worth hunting out if you''re a more experienced skater looking for something serious.', 'https://www.google.com/maps?q=-38.0938,144.3444', 4, 'North Shore area, Norlane. Deep bowl — locals only feel, but welcoming', '{"dry-ground"}', -38.0938, 144.3444, 'day', 'Research', true),
  (60, 'Point Lonsdale Skatepark (Gas Works)', 'skatepark', '{"street","quarters","rails","bellarine","coastal"}', '{"kids","teens"}', 'Free', 'Point Lonsdale', 50, '{"any"}', '< 1hr', 'Concrete slab skatepark at the iconic Gas Works site in Point Lonsdale. Heaps of quarters, rails and ledges across a large open surface. Nice spot to combine with a trip to the Point Lonsdale lighthouse and blow-hole.', 'https://www.google.com/maps?q=-38.2919,144.6184', 3, 'Gas Works site, Point Lonsdale. Combine with lighthouse walk', '{"dry-ground"}', -38.2919, 144.6184, 'day', 'Research', true),
  (61, 'Inverleigh Skatepark', 'skatepark', '{"free","country","quiet","local-knowledge","hidden-gem"}', '{"kids","teens"}', 'Free', 'Inverleigh', 45, '{"any"}', '< 1hr', 'Country skatepark in the small town of Inverleigh. Quiet and never crowded — classic hidden gem you''d only know about if someone told you. Good stop on a drive through the Barwon Valley.', 'https://www.google.com/maps/search/Inverleigh+Skatepark+Victoria', 3, 'Cnr Hamilton Hwy & East St, Inverleigh', '{"dry-ground"}', -38.1188, 144.0451, 'day', 'Research', true),
  (62, 'Distillery Creek Picnic Area', 'park', '{"picnic","BBQ","birdwatching","nature-walk","bush","ironbark","family"}', '{"all-ages"}', 'Free', 'Aireys Inlet', 18, '{"any"}', '< 1hr – half-day', 'Beautiful bush picnic area set among tall ironbark trees just behind Aireys Inlet. Two car parks — lower and upper — both with picnic tables and wood-fired BBQs (bring your own wood). Toilets and info board at upper car park. Short 1.5km nature trail loops through the ironbark forest — brilliant birdwatching. Also the trailhead for longer walks to Painkalac Dam and Moggs Creek. Links to MTB trails too. A genuine local gem — quiet and beautiful.', 'https://www.google.com/maps/search/Distillery+Creek+Picnic+Area+Aireys+Inlet', 5, 'Turn off GOR at Bambra Rd just east of Aireys Inlet shops. Follow 2.5km then left on Distillery Creek Rd', '{"dry-ground","warm"}', -38.4659, 144.1077, 'day', 'Research', true),
  (63, 'Sheoak Picnic Area', 'park', '{"picnic","BBQ","waterfalls","rainforest","walk-hub","family"}', '{"all-ages"}', 'Free', 'Lorne (hinterland)', 35, '{"any"}', 'half-day – full-day', 'The waterfall capital of Victoria — arguably the best picnic base in the whole Otways. Set among giant eucalypts and cool fern gullies, 3.5km behind Lorne. Tables, gas BBQs, toilets, info board. Hub for walks to Henderson Falls (1.5km), Kalimna Falls (4.2km), Phantom Falls (4.3km), Castle Rock lookout, and more. Glow worms visible in the gully at night near the suspension bridge. Check Parks Victoria for any closures before going — some tracks affected by 2026 flood damage.', 'https://www.google.com/maps/search/Sheoak+Picnic+Area+Lorne+Victoria', 5, 'Via Allenvale Rd, Lorne — 3.5km from GOR. Check Parks Vic for closures before visiting', '{"dry-ground","warm"}', -38.5423, 143.9908, 'day', 'Research', true),
  (64, 'Moggs Creek Picnic Area', 'park', '{"picnic","ocean-views","walk","quiet","family"}', '{"all-ages"}', 'Free', 'Aireys Inlet / Fairhaven', 20, '{"any"}', '< 1hr – half-day', 'Peaceful picnic area in Great Otway National Park near Fairhaven. Starting point for the Ocean View Track with stunning views of the Great Ocean Road, Fairhaven beach and the Southern Ocean. Quieter than Distillery Creek. Can be linked by walk to Distillery Creek for a longer adventure.', 'https://www.google.com/maps/search/Moggs+Creek+Picnic+Area+Great+Ocean+Road', 4, 'Just off the GOR between Aireys Inlet and Fairhaven', '{"dry-ground","warm"}', -38.5102, 144.0173, 'day', 'Research', true),
  (65, 'Blanket Leaf Picnic Area', 'park', '{"picnic","fireplace","shelter","tall-trees","family","Erskine-Falls"}', '{"all-ages"}', 'Free', 'Lorne (hinterland)', 35, '{"any"}', '< 1hr – half-day', 'Lovely picnic area nestled among tall eucalyptus trees in Great Otway National Park. Accessible tables, fireplaces and sheltered areas. Close to Erskine Falls and the Lemonade Creek Walk through fern gullies. Beautiful shaded spot on a hot day — stays cool under the canopy.', 'https://www.google.com/maps/search/Blanket+Leaf+Picnic+Area+Lorne+Victoria', 4, 'Near Erskine Falls Rd, Lorne hinterland', '{"dry-ground","no-fire-ban"}', -38.5487, 143.9752, 'day', 'Research', true),
  (66, 'Anglesea River Picnic Area', 'park', '{"picnic","river","family","dogs-welcome","kangaroos","easy"}', '{"all-ages"}', 'Free', 'Anglesea', 15, '{"any"}', '< 1hr', 'Flat grassy picnic area along the beautiful Anglesea River right in town. Picnic tables, BBQs, shade. Combine with a paddle at Anglesea Paddle Boats next door, a walk along the river trail, or a look for kangaroos at the golf course just up the road. Perfect easy family stop.', 'https://www.google.com/maps/search/Anglesea+River+picnic+area+Victoria', 4, 'Riverbank, Anglesea town centre. Walk distance to everything in Anglesea', '{"warm"}', -38.4062, 144.184, 'day', 'Research', true),
  (67, 'Lake Elizabeth Picnic Area', 'park', '{"picnic","platypus","lake","rainforest","magical","quiet"}', '{"all-ages"}', 'Free', 'Forrest (Otways)', 75, '{"any"}', 'half-day', 'One of Victoria''s most magical spots — a tranquil lake enclosed by tall trees and fern gullies in the Otways hinterland. Mist drifts across the water in the early hours. Picnic tables, toilets, shaded seating. Walk the lake loop trail (easy, ~1hr). Platypus regularly spotted at dawn and dusk — bring patience and binoculars. Note: campground car park closed Jan–Mar 2026 for upgrades.', 'https://www.google.com/maps/search/Lake+Elizabeth+Forrest+Victoria', 5, 'Near Forrest, Otways. Dawn/dusk = best platypus sightings. Check Parks Vic for 2026 car park closure', '{"dry-ground","warm"}', -38.5421, 143.7476, 'day', 'Research', true),
  (68, 'Painkalac Dam Picnic Spot', 'park', '{"picnic","dam","birdwatching","walking","hidden-gem","local-knowledge"}', '{"all-ages"}', 'Free', 'Aireys Inlet (hinterland)', 20, '{"any"}', '< 1hr – half-day', 'Aireys Inlet''s former water supply — now a peaceful public picnic spot. Picnic tables at the dam wall with lovely water views and excellent birdwatching. Possible platypus sighting in the creek below. Access via the walking track from Distillery Creek Picnic Area (~3km each way) or drive in on the Barwon Water access road. Very few people know about this one.', 'https://www.google.com/maps/search/Painkalac+Dam+Aireys+Inlet', 4, 'Access via Distillery Creek Rd. Very quiet — almost nobody comes here', '{"dry-ground","warm"}', -38.4667, 144.0869, 'day', 'Research', true),
  (69, 'Jan Juc Caravan Park', 'camping', '{"local","family-friendly","walking-distance","powered","dogs-seasonal"}', '{"all-ages"}', 'Cheap', 'Jan Juc', 1, '{"any"}', 'overnight', 'Your local caravan park right on Sunset Strip — ideal for visiting friends and family who want to stay close. Powered and unpowered sites, good facilities. Walking distance to the skatepark, rockpools and Jan Juc beach.', 'https://www.google.com/maps/search/Jan+Juc+Caravan+Park', 4, '93 Sunset Strip, Jan Juc. Ph: (03) 5261 2932', '{"dry-ground"}', -38.3589, 144.2991, 'both', 'Research', true),
  (70, 'Torquay Foreshore Caravan Park', 'camping', '{"beachfront","glamping","family","powered","jumping-pillow","dogs-seasonal"}', '{"all-ages"}', 'Moderate', 'Torquay', 5, '{"any"}', 'overnight', 'The only beachfront caravan park in Torquay — right on the Back Beach and Spring Creek. Great range of options: powered/unpowered sites, cabins, glamping tents and pods. Indoor games room, jumping pillow, direct beach access. Dogs welcome seasonally (May–Oct). Book well ahead in summer.', 'https://greatoceanroadparks.com.au/find-a-park/torquay', 5, 'Torquay Back Beach. Book early — fills fast in Jan/Feb', '{"any-weather"}', -38.331, 144.3258, 'both', 'Research', true),
  (71, 'Anglesea Family Caravan Park', 'camping', '{"riverside","family","powered","kangaroos","popular"}', '{"all-ages"}', 'Moderate', 'Anglesea', 15, '{"any"}', 'overnight', 'Beautifully positioned right on the Anglesea River in town. Powered and unpowered sites, cabins. Walking distance to beach, shops and restaurants. Kangaroos often wander through. Very popular — book months ahead for peak season.', 'https://www.google.com/maps/search/Anglesea+Family+Caravan+Park', 5, 'Anglesea River foreshore. One of the best positioned parks on the coast', '{"any-weather"}', -38.4044, 144.18, 'both', 'Research', true),
  (72, 'BIG4 Aireys Inlet Holiday Park', 'camping', '{"powered","family-friendly","near-lighthouse","dogs-seasonal"}', '{"all-ages"}', 'Moderate', 'Aireys Inlet', 18, '{"any"}', 'overnight', 'Well-run family park in Aireys Inlet. Powered sites, cabins, good facilities. Short walk to the Split Point Lighthouse, pub, cafes and beach. Great base for exploring Anglesea and Lorne. Dogs allowed seasonally.', 'https://www.big4.com.au/caravan-parks/vic/great-ocean-road/aireys-inlet-holiday-park', 4, '19-25 Great Ocean Rd, Aireys Inlet', '{"any-weather"}', -38.4558, 144.1029, 'both', 'Research', true),
  (73, 'Lorne Foreshore Caravan Park', 'camping', '{"riverside","glamping","family","central","popular"}', '{"all-ages"}', 'Moderate', 'Lorne', 30, '{"any"}', 'overnight', 'Three campgrounds along the Erskine River right in Lorne town. Steps from the beach, shops, cafes and restaurants. Glamping tents available for a more comfortable experience. One of the most popular parks on the coast — book very early for summer.', 'https://greatoceanroadparks.com.au/find-a-park/lorne', 5, '2 Great Ocean Rd, Lorne. Ph: (03) 5289 1382. Book 6+ months ahead for Jan', '{"any-weather"}', -38.5397, 143.9774, 'both', 'Research', true),
  (74, 'Cumberland River Holiday Park', 'camping', '{"riverside","bush","walks","secluded","family"}', '{"all-ages"}', 'Moderate', 'Cumberland River', 40, '{"any"}', 'overnight', 'Hidden gem between Lorne and Wye River on the Cumberland River. Cabins and campsites in a stunning bush riverside setting. Walks straight into the Otways from camp. Beautiful beach opposite. River has great swimming holes to cool off. Much quieter than Lorne.', 'https://www.google.com/maps/search/Cumberland+River+Holiday+Park+Victoria', 5, '2680 Great Ocean Rd, Cumberland River. Ph: (03) 5289 1790', '{"any-weather"}', -38.5559, 143.9601, 'both', 'Research', true),
  (75, 'Wye River Foreshore Camping', 'camping', '{"beachfront","small-town","foreshore","unpowered","family"}', '{"all-ages"}', 'Cheap', 'Wye River', 48, '{"any"}', 'overnight', 'Foreshore camping in the gorgeous little town of Wye River. Right on the beach — fall asleep to the sound of waves. Unpowered sites, basic facilities. The town itself is tiny and beautiful. Books out very fast — one of the most sought-after spots on the coast.', 'https://www.google.com/maps/search/Wye+River+Foreshore+Camping+Reserve', 5, 'Books out months ahead. Check availability early', '{"dry-ground"}', -38.6085, 143.8781, 'both', 'Research', true),
  (76, 'BIG4 Wye River Holiday Park', 'camping', '{"powered","family","facilities","Wye-River"}', '{"all-ages"}', 'Moderate', 'Wye River', 48, '{"any"}', 'overnight', 'The more facilities-focused option at Wye River. Powered sites, amenities blocks, camp kitchen. Better chance of availability than the foreshore reserve. Still a magical little coastal town to base yourself in.', 'https://www.big4.com.au/caravan-parks/vic/great-ocean-road/wye-river-holiday-park', 4, 'Wye River township', '{"dry-ground"}', -38.6085, 143.8781, 'both', 'Research', true),
  (77, 'Kennett River Family Caravan Park', 'camping', '{"old-school","bush","koala-walk","family","grassy"}', '{"all-ages"}', 'Moderate', 'Kennett River', 55, '{"any"}', 'overnight', 'A beloved old-school park — dirt roads, grassy sites under the gums, lots of space between sites. Right next to the famous Kennett River Koala Walk where koalas are almost guaranteed in the trees. Unpretentious and brilliant.', 'https://www.google.com/maps/search/Kennett+River+Family+Caravan+Park', 5, 'Kennett River, Great Ocean Rd. Koalas in the trees above camp', '{"dry-ground"}', -38.6581, 143.7214, 'both', 'Research', true),
  (78, 'Bimbi Park – Camp under Koalas', 'camping', '{"koalas","bush","campfire","glamping","family","wildlife","Cape-Otway"}', '{"all-ages"}', 'Moderate', 'Cape Otway', 90, '{"any"}', 'overnight', 'Camp under Manna Gum trees absolutely filled with koalas. Family-run park that''s been a favourite for decades. Powered and unpowered sites, cabins, glamping tents, campfire allowed. Camp kitchen, kiosk, laundry. Dark skies — brilliant for stargazing. Close to Cape Otway Lighthouse. One of the most special camps in Victoria.', 'https://www.bimbipark.com.au', 5, '90 Manna Gum Dr, Cape Otway. Book ahead — very popular', '{"clear-sky","no-fire-ban"}', -38.8548, 143.5177, 'both', 'Research', true),
  (79, 'Forrest Caravan Park', 'camping', '{"MTB-base","bush","family","powered","Forrest"}', '{"all-ages"}', 'Cheap', 'Forrest', 75, '{"any"}', 'overnight', 'The perfect base for a Forrest MTB weekend. Right in the heart of Forrest township, walking distance to the trails and the famous Forrest Brewing Company. Powered and unpowered sites. Book ahead for the Otway Odyssey MTB race weekend in February.', 'https://www.google.com/maps/search/Forrest+Caravan+Park+Victoria', 4, '1 Station St, Forrest. Ph: (03) 5236 6272', '{"dry-ground"}', -38.5238, 143.7259, 'both', 'Research', true),
  (80, 'Big Hill Campground', 'camping', '{"bush-camping","free-ish","dogs-ok","quiet","Otways"}', '{"teens","adults"}', 'Cheap', 'Lorne-Deans Marsh Rd', 35, '{"any"}', 'overnight', 'Peaceful bush campground in the Otways. Drop toilets and rainwater tanks. $15.70/night via Parks Victoria — used to be free. Dogs allowed (not in a national park). Can get busy with 4WD riders on weekends. Dark skies — good stargazing. Phone reception is patchy — enjoy the disconnect.', 'https://www.google.com/maps/search/Big+Hill+Campground+Otways+Victoria', 4, 'Intersection of Big Hill Track & Lorne-Deans Marsh Rd. Book via Parks Vic', '{"dry-ground"}', -38.5779, 143.9166, 'both', 'Research', true),
  (81, 'Allenvale Campground', 'camping', '{"walk-in","riverside","tiny","secluded","Lorne"}', '{"teens","adults"}', 'Cheap', 'Behind Lorne', 32, '{"spring","summer","autumn"}', 'overnight', 'Intimate walk-in campground (just 230m from the carpark) on the banks of the St George River. Very small — a handful of sites only. Peaceful and secluded. Great access to Lorne''s waterfall walking tracks. Not suitable for caravans or large rigs.', 'https://www.google.com/maps/search/Allenvale+Campground+Lorne+Victoria', 4, 'Short walk from Allenvale Rd carpark behind Lorne', '{"dry-ground"}', -38.556, 143.971, 'both', 'Research', true),
  (82, 'Jamieson Creek Campground', 'camping', '{"renovated","riverside","tents-caravans","walks","ocean-views"}', '{"all-ages"}', 'Cheap', 'Skenes Creek / Wye River', 55, '{"any"}', 'overnight', 'Newly renovated compact campground near Skenes Creek. Accepts tents, caravans and camper trailers. Panoramic ocean views from camp. Direct access to walking tracks to Wye River and beyond. Peaceful and well-positioned in the Otways hinterland.', 'https://www.google.com/maps/search/Jamieson+Creek+Campground+Victoria', 4, 'Near Skenes Creek. Book via Parks Victoria', '{"dry-ground"}', -38.5959, 143.8577, 'both', 'Research', true),
  (83, 'Lake Elizabeth Campground', 'camping', '{"platypus","glow-worms","forest","basic","MTB-base"}', '{"all-ages"}', 'Cheap', 'Forrest (Otways)', 75, '{"any"}', 'overnight', 'Basic bush camping in the forest right near Lake Elizabeth. Famous for platypus sightings at dawn and dusk, and glow worms at night. Drop toilets, untreated rainwater. No fires. Links directly to Forrest MTB trails. ⚠️ Car park closed Jan–Mar 2026 for upgrades — check Parks Vic before going.', 'https://www.google.com/maps/search/Lake+Elizabeth+Campground+Forrest+Victoria', 5, '~$14.50/night. Check Parks Vic — car park closed until late March 2026', '{"dry-ground"}', -38.5421, 143.7476, 'both', 'Research', true),
  (84, 'Blanket Bay Campground', 'camping', '{"coastal-forest","rockpools","koalas","unpowered","Cape-Otway"}', '{"all-ages"}', 'Cheap', 'Cape Otway', 95, '{"any"}', 'overnight', 'Stunning campground right in the forest on the coastal shores of Cape Otway. 22 unpowered sites for tents, caravans and motorhomes. Sheltered bay perfect for swimming. Rockpools teeming with marine life. Koalas in the trees above. Dark skies, very remote feel. Book via Parks Victoria — popular and fills fast.', 'https://www.google.com/maps/search/Blanket+Bay+Campground+Cape+Otway', 5, 'Blanket Bay Rd, Cape Otway. Book via Parks Vic — especially summer', '{"clear-sky"}', -38.8348, 143.5383, 'both', 'Research', true),
  (85, 'Parker Hill Campground', 'camping', '{"very-basic","bush","remote","Cape-Otway","dark-skies"}', '{"teens","adults"}', 'Cheap', 'Cape Otway', 95, '{"any"}', 'overnight', 'Very basic and beautiful bush camping near Cape Otway. No power, drop toilets only. For those who want true wilderness. Dark skies are exceptional — excellent stargazing. Book via Parks Victoria.', 'https://www.google.com/maps/search/Parker+Hill+Campground+Cape+Otway', 4, 'Parker Hill Track, Cape Otway. Book via Parks Vic', '{"clear-sky"}', -38.8282, 143.543, 'both', 'Research', true),
  (86, 'Milky Way Stargazing – Surf Coast', 'night', '{"stargazing","Milky-Way","free","dark-sky","astrophotography","family"}', '{"all-ages"}', 'Free', 'Bells Beach / Point Addis / Jan Juc', 0, '{"winter","autumn"}', '< 1hr – half-day', 'The Surf Coast sits at a perfect latitude and away from major city light pollution — ideal for naked-eye Milky Way on clear moonless nights. Best local spots: Bells Beach car park (faces south, no artificial light), Point Addis headland, and Jan Juc beach looking south. Best season: autumn–winter when the galactic core is highest. Best conditions: new moon, clear skies, no wind. Use the Stellarium or SkySafari app to identify what you''re seeing. Bring a blanket, red torch (preserves night vision), and hot drinks.', 'https://www.google.com/maps/search/Bells+Beach+Torquay+Victoria', 5, 'New moon = best. Check Weather & Moon Phase apps first. Red torch only to preserve night vision', '{"clear-sky","new-moon","low-wind"}', -38.3721, 144.2829, 'night', 'Research', true),
  (87, 'Aurora Australis (Southern Lights) Chase', 'night', '{"aurora","southern-lights","celestial","rare","photography","night"}', '{"all-ages"}', 'Free', 'Jan Juc / Bells Beach / Point Addis', 0, '{"winter","spring"}', '< 1hr', 'The Surf Coast is one of the best mainland spots in Victoria for Aurora Australis sightings. Confirmed sightings from Bells Beach and Torquay — locals report the whole of Torquay came out for a particularly spectacular display in early 2026. Face south with a clear horizon (Bells Beach or Jan Juc beach). Best months: May–August, also September equinox. How to track: subscribe to BoM Space Weather alerts, use SpaceWeatherLive or My Aurora Forecast app, join the Aurora Australis Australia Facebook group for real-time alerts. Camera tip: even a phone camera on night mode will often capture colour the naked eye misses.', 'https://www.sws.bom.gov.au/Aurora', 5, 'Set up aurora alerts on your phone — it happens with only 30min warning. Always face south', '{"clear-sky","low-wind","geomagnetic-storm"}', -38.3682, 144.296, 'night', 'Research', true),
  (88, 'Bioluminescence / Sea Sparkle Watch', 'night', '{"bioluminescence","sea-sparkle","magical","rare","night","beach"}', '{"all-ages"}', 'Free', 'Jan Juc / Lorne / Surf Coast beaches', 0, '{"summer","autumn"}', '< 1hr', 'One of the most magical natural phenomena you can witness locally — and it happens here. Bioluminescent waves (Sea Sparkle / Noctiluca scintillans) light the surf up blue. Confirmed sighting: Surf Coast near Lorne, June 2025. Best conditions: calm warm nights, dark moon, after calm sunny days. Walk through wet sand or disturb the water at the shoreline to trigger the glow. Any south-facing beach works — Jan Juc, Bells Beach, Fairhaven, Lorne. Track sightings on the Bioluminescence Australia Facebook group.', 'https://www.facebook.com/groups/BioluminescenceAustralia', 5, 'Can''t be predicted — join the Bioluminescence Australia FB group for local alerts', '{"calm-sea","new-moon","warm"}', -38.3682, 144.296, 'night', 'Research', true),
  (89, 'Glow Worm Walk – Sheoak / Allenvale', 'night', '{"glow-worms","night-walk","magical","rainforest","family"}', '{"all-ages"}', 'Free', 'Lorne (hinterland)', 32, '{"any"}', '< 1hr', 'After dark, the suspension bridge gully at Sheoak Picnic Area comes alive with glow worms. Tiny bioluminescent larvae of fungus gnats clinging to the moist fern-covered banks. Walk slowly with a red torch only — white light kills the experience. Also visible along the Allenvale track. Combine with a night walk to listen to the forest come alive with frogs and owls. Free, no booking needed — just go after dark.', 'https://www.google.com/maps/search/Sheoak+Picnic+Area+Lorne+Victoria', 5, 'Red torch only! Take it slowly. Wettest months = most glow worms', '{"new-moon"}', -38.5423, 143.9908, 'night', 'Research', true),
  (90, 'Snake Valley Dark Sky Site (Ballarat region)', 'night', '{"dark-sky","official","astronomy","telescope","events","ballarat"}', '{"all-ages"}', 'Free', 'Snake Valley (nr Ballarat)', 100, '{"any"}', 'overnight', 'Official Australian Dark Sky Site — one of the best in Victoria. Run by the Snake Valley Astronomical Association. Monthly club nights open to visitors, astronomy classes, telescope viewing. Moon, nebulae, star clusters, galaxies. About 100km from Jan Juc — worth combining with a Ballarat day trip. Check their website for public event dates before going.', 'https://www.google.com/maps/search/Snake+Valley+Astronomical+Association+Victoria', 4, '825 Linton-Carngham Rd, Snake Valley. Check event calendar — not open every night', '{"clear-sky","new-moon","low-wind"}', -37.457, 143.5688, 'night', 'Research', true),
  (91, 'Whale Watching – Point Addis Headland', 'night', '{"whales","wildlife","seasonal","free","binoculars","clifftop"}', '{"all-ages"}', 'Free', 'Point Addis', 8, '{"winter","spring"}', '< 1hr – half-day', 'Point Addis headland is one of the closest spots to Jan Juc for land-based whale watching. Southern Right Whales, Humpbacks and occasionally Orcas pass close to shore June–October during their annual migration. The high clifftop gives an excellent vantage point — whales sometimes come within metres of the cliffs. Bring binoculars. Best in calm conditions when the sea surface is smooth — blows are easy to spot. Dawn and dusk are best — calmer seas and better light. Also good for spotting dolphins and seabirds year-round.', 'https://www.google.com/maps/search/Point+Addis+Marine+National+Park+Victoria', 5, 'June–October. Face north-west from the headland. Binoculars essential. Dawn/dusk best', '{"calm-sea","clear-sky"}', -38.3975, 144.2534, 'night', 'Research', true),
  (92, 'Whale Watching – Teddy''s Lookout, Lorne', 'night', '{"whales","lookout","scenic","seasonal","free","binoculars"}', '{"all-ages"}', 'Free', 'Lorne', 30, '{"winter","spring"}', '< 1hr', 'Teddy''s Lookout is one of the best whale watching vantage points on the Surf Coast — high above the coast where the St George River meets the sea. Southern Right Whales and Humpbacks pass by June–October. Also one of the most spectacular sunset and moonrise viewpoints on the entire Great Ocean Road. Short walk from the car park. No cost, no booking.', 'https://www.google.com/maps/search/Teddys+Lookout+Lorne+Victoria', 5, 'William St, Lorne. Also brilliant for sunrise/sunset — combine both', '{"calm-sea","clear-sky"}', -38.5403, 143.9796, 'night', 'Research', true),
  (93, 'Sunset at Point Danger / Yellow Bluff', 'night', '{"sunset","clifftop","free","photography","romantic","local"}', '{"all-ages"}', 'Free', 'Torquay', 4, '{"any"}', '< 1hr', 'Point Danger and Yellow Bluff are the best local sunset spots — high clifftop lookouts just north of Torquay with sweeping views west along the coast. On a clear evening the sky lights up orange and pink over the ocean. Very easy walk from the Torquay carpark. Bring a drink and a blanket. A genuinely magical spot that locals take for granted.', 'https://www.google.com/maps/search/Point+Danger+Torquay+Victoria', 5, 'Short walk from Torquay Front Beach car park. Face west for the full show', '{"clear-sky","low-wind"}', -38.3556, 144.3124, 'night', 'Research', true),
  (94, 'Sunset at Split Point Lighthouse', 'night', '{"sunset","lighthouse","iconic","photography","Aireys-Inlet"}', '{"all-ages"}', 'Free', 'Aireys Inlet', 18, '{"any"}', '< 1hr', 'The Split Point Lighthouse (from Round the Twist!) on the clifftop at Aireys Inlet is one of the most photogenic sunset spots on the coast. The lighthouse glows warm against a golden sky, with Eagle Rock visible below. Combine with a walk along the clifftop track and dinner at the Aireys Inlet pub afterwards.', 'https://www.google.com/maps/search/Split+Point+Lighthouse+Aireys+Inlet', 5, 'Walk up from the Aireys Inlet carpark. Free to walk the grounds', '{"clear-sky"}', -38.4607, 144.1032, 'night', 'Research', true),
  (95, 'Moonrise Watch – Bells Beach / Jan Juc', 'night', '{"moonrise","full-moon","free","photography","celestial","romantic"}', '{"all-ages"}', 'Free', 'Bells Beach / Jan Juc', 2, '{"any"}', '< 1hr', 'One of the most underrated experiences on the Surf Coast — watching the full moon rise out of the Southern Ocean from Bells Beach or the Jan Juc cliffs. The moon comes up orange and enormous on the eastern horizon, tracking across the ocean. Best from the Bells Beach car park or the clifftop path at Jan Juc looking east/south-east. Check a moon phase calendar and plan around the full moon — it rises at sunset and is visible all night. Bring a tripod for photos if you have one.', 'https://www.google.com/maps/search/Bells+Beach+Torquay+Victoria', 5, 'Use TimeandDate.com or Moon+ app to find exact moonrise time and direction', '{"clear-sky","full-moon","low-wind"}', -38.3721, 144.2829, 'night', 'Research', true),
  (96, 'Night Fishing – Jan Juc Creek / Rocks', 'night', '{"fishing","night","local","free","teens","adults","squid"}', '{"teens","adults"}', 'Free', 'Jan Juc', 0, '{"any"}', '< 1hr – half-day', 'Jan Juc has a few good local spots for evening and night fishing. The creek mouth and rock platforms are popular for squid, flathead and salmon after dark. Squid are especially good at night — use a jig and a light source at the water surface. Always check local fishing rules and size limits. Torch, warm layers and a thermos are essential gear.', 'https://www.google.com/maps/search/Jan+Juc+Creek+Victoria', 4, 'Check VFA fishing rules. A fishing licence is required in Victoria for those 18+', '{"low-tide","calm-sea"}', -38.3655, 144.2978, 'night', 'Research', true),
  (97, 'Night Fishing – Torquay Pier / Front Beach', 'night', '{"fishing","night","pier","squid","snapper","family"}', '{"teens","adults"}', 'Free', 'Torquay', 4, '{"any"}', '< 1hr – half-day', 'The Torquay foreshore and pier area are popular after-dark fishing spots. Squid jigging under lights at the pier is productive in the right conditions. Salmon, flathead and snapper also taken from the rocks and beach at night. The Fisherman''s Beach area is a local favourite. A good social activity — often find other anglers happy to share tips.', 'https://www.google.com/maps/search/Torquay+Fishermans+Beach+Victoria', 4, 'Fishing licence required (18+). Best in autumn and winter for squid', '{"high-tide","calm-sea"}', -38.3269, 144.3252, 'night', 'Research', true),
  (100, 'Pub Trivia Night – Surf Coast', 'night', '{"trivia","pub","community","social","family-friendly","fun"}', '{"adults","teens"}', 'Cheap', 'Torquay / Anglesea', 5, '{"any"}', '< 1hr – half-day', 'Several pubs on the Surf Coast run regular trivia nights — a great way to meet the community. The Sands Hotel in Torquay and various Anglesea venues run weekly or monthly trivia. Teams of 4–6, prizes for winners. Check with local venues for current schedules — they change seasonally.', 'https://www.google.com/maps/search/The+Sands+Hotel+Torquay+Victoria', 4, 'Call ahead to confirm trivia nights are running — schedules change seasonally', '{"any-weather"}', -38.329, 144.3245, 'night', 'Research', true),
  (102, 'Backyard Bonfire / Fire Pit Night', 'night', '{"at-home","fire","community","free","cosy","winter","social"}', '{"all-ages"}', 'Free', 'Home / Jan Juc', 0, '{"autumn","winter","spring"}', 'half-day', 'Nothing beats a backyard fire pit on a clear Surf Coast evening. Invite the neighbours. Toasted marshmallows, stories, guitars optional. On a clear night the stars above Jan Juc are brilliant — combine with some naked-eye stargazing. Always check current fire restrictions before lighting (Vic Fire Danger Rating). Use the VicEmergency app or CFA website for daily fire danger ratings.', 'https://www.emergency.vic.gov.au/prepare/know-your-risk/fire-danger-ratings', 5, 'Always check CFA fire danger rating first. Never light a fire on a Total Fire Ban day', '{"no-fire-ban","clear-sky"}', -38.3655, 144.2978, 'night', 'Research', true),
  (103, 'Outdoor Movie Night at Home', 'night', '{"at-home","movies","family","free","projector","fun"}', '{"all-ages"}', 'Free', 'Home / Jan Juc', 0, '{"summer","autumn","spring"}', 'half-day', 'Set up a projector or big screen in the backyard. Hire a projector from a local AV store, or invest in a budget one — they''ve come down hugely in price. String some lights, set up bean bags and blankets. Vote on a film, make themed popcorn. Warm summer evenings on the Surf Coast are perfect for this. Invite neighbours for a community screening.', null, 5, 'Budget projectors from ~$80 on Amazon. Needs a white wall or sheet', '{"warm","dry-trails"}', -38.3655, 144.2978, 'night', 'Research', true),
  (104, 'Meteor Shower Watching', 'night', '{"meteor-shower","celestial","free","seasonal","family","stargazing"}', '{"all-ages"}', 'Free', 'Bells Beach / Point Addis / Jan Juc beach', 2, '{"any"}', '< 1hr', 'Several major meteor showers are visible from the Surf Coast each year. Key annual events: Eta Aquarids (late April–May, peak ~May 6, best in southern hemisphere), Southern Delta Aquarids (late July–August), Orionids (October), Geminids (December). Head to a dark south-facing beach — Bells Beach car park or Jan Juc beach are perfect. Lie flat on a blanket, let eyes adjust for 20 minutes, face away from any lights. No equipment needed — naked eye is best for shooting stars. Use the Meteor Shower app or TimeandDate.com for exact peak dates each year.', 'https://www.timeanddate.com/astronomy/meteor-shower/', 5, 'Eta Aquarids (May) is the best for southern hemisphere — up to 50 meteors/hour at peak', '{"clear-sky","new-moon","low-wind"}', -38.3721, 144.2829, 'night', 'Research', true),
  (105, 'ISS (Space Station) Spotting', 'night', '{"ISS","space-station","celestial","free","family","quick","fun"}', '{"all-ages"}', 'Free', 'Jan Juc / anywhere', 0, '{"any"}', '< 1hr', 'The International Space Station passes over Jan Juc regularly and is easily visible to the naked eye — it looks like a fast-moving, very bright star tracking silently across the sky. Takes about 2–3 minutes to cross the whole sky. Use the NASA Spot the Station website or the ISS Detector app for exact pass times. Set an alert for ''bright passes'' — magnitude -3 or brighter are spectacular. A brilliant quick activity — works from your own backyard.', 'https://spotthestation.nasa.gov', 5, 'Free alerts at spotthestation.nasa.gov — set your location to Torquay. Kids love it', '{"clear-sky","low-wind"}', -38.3655, 144.2978, 'night', 'Research', true),
  (106, 'Planet Watching – Naked Eye Planets', 'night', '{"planets","celestial","free","educational","family","stargazing"}', '{"all-ages"}', 'Free', 'Jan Juc / anywhere', 0, '{"any"}', '< 1hr', 'Venus, Jupiter, Saturn and Mars are all visible to the naked eye from Jan Juc on clear nights — no telescope needed. Jupiter is so bright it''s unmissable. Saturn looks slightly cream-yellow. Venus is the brilliant ''evening star'' or ''morning star'' depending on the season. Use the free Stellarium app (point your phone at the sky) to identify everything you can see. On a good night with dark-adapted eyes you can also see the Magellanic Clouds — two small galaxies visible only from the southern hemisphere.', 'https://stellarium-web.org', 5, 'Stellarium app is free and brilliant for kids. Point phone at sky to identify planets & constellations', '{"clear-sky","low-wind"}', -38.3655, 144.2978, 'night', 'Research', true),
  (108, 'Anglesea Movie Club', 'cinema', '{"film","monthly","community","local","indoor","social"}', '{"adults","teens"}', 'Cheap', 'Anglesea', 15, '{"any"}', 'half-day', 'Monthly community film screenings at the Anglesea Community House. 70–110 people per session — genuinely beloved local institution. Membership is $77/year (concession $66) — great value for regular attendees. Check Anglesea Community House for current screening calendar.', 'https://anglesea.org.au', 4, 'Membership required. Check ACH website or Facebook for screening dates', '{"good-in-rain"}', -38.4044, 144.1829, 'both', 'Research', true),
  (110, 'Anglesea Resale Shed (Tip Shop)', 'community', '{"secondhand","sustainability","bargains","community","free-to-browse"}', '{"all-ages"}', 'Free', 'Anglesea Transfer Station', 15, '{"any"}', '< 1hr', 'Secondhand goods shed at the Anglesea Transfer Station — run by the Anglesea Community House in partnership with Surf Coast Shire. Everything from furniture to books to kitchen gear. Sale profits go back to local community groups. A great sustainable alternative to buying new — and you never know what you''ll find.', 'https://anglesea.org.au/community/community-support/anglesea-resale-shed-at-anglesea-tip-shop/', 4, 'Anglesea Transfer Station. Call ACH on (03) 5263 2116 for opening hours', '{"any-weather"}', -38.4044, 144.1844, 'day', 'Research', true),
  (111, 'Otway Ranges Community Choir', 'community', '{"choir","singing","community","all-abilities","weekly","social"}', '{"adults","teens"}', 'Cheap', 'Anglesea', 15, '{"any"}', '< 1hr', 'Community choir open to all ages and abilities — no experience needed. Recently received Surf Coast Shire grant funding for a choir master. Weekly rehearsals. A brilliant way to meet people and do something creative together. Contact Anglesea Community House for current schedule.', 'https://anglesea.org.au', 4, 'Check ACH website for rehearsal times and location', '{"good-in-rain"}', -38.4044, 144.1829, 'day', 'Research', true),
  (112, 'Aireys Inlet Community Garden', 'community', '{"gardening","community","sustainable","free","growing","local"}', '{"all-ages"}', 'Free', 'Aireys Inlet', 18, '{"any"}', '< 1hr – half-day', 'Community growing space in Aireys Inlet — just received new greenhouse funding from Surf Coast Shire. A great place to grow food together, share seeds and learn from neighbours. The repair cafe and community garden community often overlap — both based out of the Aireys Inlet hall precinct.', 'https://www.google.com/maps/search/Aireys+Inlet+Community+Garden+Victoria', 4, 'Check local Aireys Inlet community Facebook page for working bee dates', '{"warm"}', -38.4558, 144.1029, 'day', 'Research', true),
  (117, 'Lorne Theatre', 'cinema', '{"cinema","art-deco","heritage","film","iconic","coastal","single-screen"}', '{"all-ages"}', 'Moderate', 'Lorne', 74, '{"any"}', '~2hrs', 'One of the great cinema experiences in Victoria — an Art Deco single-screen theatre on Mountjoy Parade in Lorne, operating since 1937. The 550-seat auditorium has terrazzo floors, geometric ceiling panels, metal balustrading and a mezzanine. Currently managed by the team behind Melbourne''s Rooftop Cinema and Sydney''s Golden Age Cinema & Bar. Screens a mix of new releases and curated titles, plus occasional live music and special events. The drive down the Great Ocean Road to catch a film here is an experience in itself — go on a summer evening and arrive early to walk along the foreshore first. Heritage-listed and genuinely special. Worth the 74km for a memorable family or date night.', 'https://lornetheatre.ourgoldenage.com.au', 4, 'Check website before visiting — management and programming have been in transition. Licensed candy bar. Available for private hire.', '{"good-in-rain"}', -38.5398, 143.9779, 'both', 'Research', true),
  (118, 'The Pivotonian Cinema (The Piv)', 'cinema', '{"cinema","arthouse","independent","geelong","local","dolby-atmos","licensed-bar","film"}', '{"teens","adults"}', 'Moderate', 'South Geelong', 22, '{"any"}', '~2hrs', 'Geelong''s only independent cinema, screening a hand-picked mix of arthouse, international and quality mainstream films daily. The Piv is genuinely loved locally — comfy armchairs, beanbags, Dolby Atmos surround sound, and a licensed bar serving local beers and wines you can take into the cinema. Named after the ''Pivotonians'' — the historic Gold Rush-era term for Geelong locals. Hosts special events, filmmaker Q&As and local short film nights throughout the year. Far better than a multiplex for anything arthouse, documentary or international. South Geelong train station is literally at the end of Verner Street — easy to do car-free.', 'https://pivotcinema.com.au', 4, 'Cnr Moorabool & Verner Streets, South Geelong. Daily screenings — check website. South Geelong train station steps away. Good public transport option.', '{"good-in-rain"}', -38.1518, 144.3631, 'both', 'Research', true),
  (119, 'Village Cinemas Geelong', 'cinema', '{"cinema","multiplex","blockbuster","gold-class","geelong","family","new-releases"}', '{"all-ages"}', 'Moderate', 'Geelong CBD', 21, '{"any"}', '~2hrs', 'Nine-screen multiplex in Geelong''s Market Square — the go-to for new releases, blockbusters and school holiday films. Two Gold Class theatres available for a genuinely luxurious night out (reclining seats, waiter service, cocktails). Great for family school holiday outings when you want a reliable big screen experience. Parking validated at box office during shopping centre hours; free parking under the cinema evenings and weekends.', 'https://villagecinemas.com.au/cinemas/geelong', 3, '194-200 Ryrie Street, Geelong CBD. Ph: 1300 555 400. Book online for peak times — school holiday sessions fill fast. Gold Class worth it for a special night.', '{"good-in-rain"}', -38.1486, 144.3612, 'both', 'Research', true),
  (120, 'Reading Cinemas Waurn Ponds', 'cinema', '{"cinema","multiplex","budget","family","waurn-ponds","blockbuster","new-releases"}', '{"all-ages"}', 'Cheap', 'Waurn Ponds', 17, '{"any"}', '~2hrs', 'The closest multiplex to Jan Juc — 8 screens at Waurn Ponds Shopping Centre. Well known for consistently lower ticket prices than Village, making it the budget-friendly family cinema option. The Titan Theater is a premium large-format screen with extra-wide leather seats and personal tables — a nice upgrade without Gold Class prices. Good if you''re heading to Geelong for shopping anyway; easy to add a session without going all the way into the CBD.', 'https://readingcinemas.com.au/cinemas/all-sessions/waurnponds', 3, 'Cnr Princes Hwy & Pioneer Rd, Waurn Ponds. Ph: (03) 5249 2800. Tickets from ~$17. Parking at Waurn Ponds Shopping Centre.', '{"good-in-rain"}', -38.2116, 144.3027, 'both', 'Research', true),
  (121, 'Barwon Heads Film Society', 'cinema', '{"film-society","arthouse","monthly","documentary","animation","community","local","barwon-heads"}', '{"adults","teens"}', 'Cheap', 'Barwon Heads', 28, '{"any"}', '~2hrs', 'A genuine local gem — the Barwon Heads Film Society screens a monthly program of arthouse, documentary, animation and classic films at the Barwon Heads Community Hall. Small, intimate, community-run — a very different experience to a multiplex. Has also run special summer film nights as part of larger community programs. If you love film that goes beyond mainstream releases, this is your crowd. Membership is required and very affordable. A great reason to explore the Bellarine Peninsula too — Barwon Heads is a lovely coastal town worth the trip.', 'https://www.facebook.com/BarwonHeadsFilmSociety/', 4, 'Monthly screenings at Barwon Heads Community Hall. Membership required — check Facebook for current season schedule and dates. Door entry usually available.', '{"good-in-rain"}', -38.2773, 144.4963, 'both', 'Research', true),
  (123, 'Jan Juc Coast Action – Working Bees', 'volunteering', '{"volunteering","environment","revegetation","conservation","working-bee","local","jan-juc","coastal"}', '{"all-ages"}', 'Free', 'Jan Juc', 0, '{"any"}', '~2hrs', 'One of the most meaningful things you can do locally. Jan Juc Coast Action has been revegetating and protecting the Jan Juc cliffs since 1994 — and the transformation over three decades is remarkable (before/after photos at Steps Lookout make it very tangible for kids). The group has 90 members with around 20 showing up each working bee for weeding, planting and mulching along the clifftops between Bird Rock and Steps Lookout. Tools provided, no experience needed — regulars are generous with knowledge. Morning tea and a chat at the end is part of the deal. The group also built Surf Coast Nature Search (scnaturesearch.com.au) — a free online plant ID tool for the local coastline that''s brilliant for curious kids. Perfect Sunday morning activity.', 'https://www.facebook.com/JanJucCoastAction', 5, 'First Sunday of every month, 10am (not January). Meet at Jan Juc cliffs — check Facebook for exact location each month. Contact Luke Hynes 0406 113 438.', '{"dry-trails"}', -38.3655, 144.2978, 'day', 'Research', true),
  (124, 'Torquay Coast Action – Working Bees', 'volunteering', '{"volunteering","environment","revegetation","conservation","working-bee","torquay","coastal","weeds"}', '{"all-ages"}', 'Free', 'Torquay', 4, '{"any"}', '~2hrs', 'Torquay Coast Action has been restoring the coastal dunes and foreshore from Point Impossible to Point Danger since 1995 — tackling invasive woody weeds and revegetating key sites like Deep Creek river mouth, Voss''s Car Park and Horseshoe Bend Road. These sites are now high-value native wildlife habitat that didn''t exist 30 years ago. Monthly working bees rotate around different Torquay coastal reserves. Friendly, social group with a great mix of long-time locals and newer faces. Tools provided, all welcome. A good way to learn the ecological story behind the coast you''re surfing and walking every day.', 'https://www.gorcc.com.au/volunteer/torquay-district/', 4, 'Fourth Sunday of every month (not January), 10am. Location rotates — check GORCC website or contact Glenda Shomaly 5261 6266.', '{"dry-trails"}', -38.3364, 144.3239, 'day', 'Research', true),
  (125, 'ANGAIR Working Bees – Anglesea & Aireys Inlet', 'volunteering', '{"volunteering","environment","weeds","flora","fauna","anglesea","aireys","conservation","working-bee"}', '{"adults","teens"}', 'Free', 'Anglesea', 20, '{"any"}', '~2hrs', 'ANGAIR (Anglesea Aireys Inlet Society for the Protection of Flora and Fauna) has been protecting the internationally significant Anglesea heathlands since 1969 — one of the most biodiverse coastal ecosystems in Victoria. Working bees run three Monday mornings per month, 9:30–11am, across sites from Anglesea to Aireys Inlet. Work involves removing invasive weeds like Hakea sericea and Boneseed from nature reserves, Coastal Moonah Woodland and the Great Otway National Park. All tools provided; morning tea at the ANGAIR Natural History Centre afterwards. The group also runs guided wildflower walks, plant propagation, and educational programs. Excellent if you want to go deep on local botany — the expertise in this group is exceptional.', 'https://angair.org.au', 4, 'Three Monday mornings per month, 9:30am. Meet at ANGAIR office, 3C McMillan St Anglesea. Check angair.org.au events calendar for dates. Membership available but not required for working bees.', '{"dry-trails"}', -38.4044, 144.1829, 'day', 'Research', true),
  (127, 'Surfrider Foundation – Surf Coast Branch', 'volunteering', '{"environment","ocean","activism","beach-clean","community","monthly","torquay","sustainability","coastal"}', '{"teens","adults"}', 'Free', 'Torquay', 4, '{"any"}', '~2hrs', 'The local branch of Australia''s most active coastal conservation organisation. Surfrider Surf Coast has been running since 1996 — starting with protests against sewage outfalls at Black Rock and Lorne, and growing into a serious force for coast protection. They''ve successfully campaigned against offshore fossil fuel exploration, led beach clean-ups including a famous Jan Juc litter blitz that filled 25 large bags, and run paddle-out protests at Cosy Corner when needed. Monthly meetings are held the second Wednesday of each month, 7:30pm at Four Pines Torquay — a laid-back, pub-style gathering open to anyone who cares about the coast. Good mix of surfers, families and community members. If you want to do something that actually moves the needle on ocean protection locally, this is the crowd.', 'https://www.surfrider.org.au/surfcoast/', 4, 'Monthly meetings: 2nd Wednesday, 7:30pm at Four Pines Torquay. Also runs occasional beach cleans and actions — follow on social media for event dates.', '{"any-weather"}', -38.329, 144.3245, 'day', 'Research', true),
  (128, 'SANE – Surfers Appreciating Natural Environment', 'volunteering', '{"volunteering","environment","bells-beach","conservation","revegetation","coastal","working-bee"}', '{"all-ages"}', 'Free', 'Bells Beach / Point Addis', 5, '{"any"}', '~2hrs', 'SANE has been protecting the Bells Beach Reserve since 1988 — one of the longest-running coastal volunteer groups on the Surf Coast with over 100 members. The group focuses on the reserve between Bells Beach and Point Addis, combating human pressures from growing visitor numbers through revegetation, weed removal and habitat restoration. As stewards of one of the most iconic surf spots in the world, SANE volunteers have a genuine connection to the place. Great group for anyone who surfs Bells regularly and wants to give something back to the place that''s given them so much. Check GORCC''s website or ask at Torquay surf shops for current working bee schedule.', 'https://www.gorcc.com.au/volunteer/torquay-district/', 4, 'Regular working bees — check GORCC volunteer page for schedule. Contact via GORCC (gorcc.com.au) for current meeting times.', '{"dry-trails"}', -38.3721, 144.2829, 'day', 'Research', true),
  (129, 'Torquay Landcare Group', 'volunteering', '{"landcare","environment","sustainability","habitat","biodiversity","torquay","volunteering","agriculture"}', '{"adults","teens"}', 'Free', 'Torquay', 4, '{"any"}', 'half-day', 'The Torquay and District Landcare Group has been operating since 1990 with 50+ members, working across the Torquay hinterland, Freshwater Creek and Spring Creek catchments on sustainable land and natural resource management. Projects have included major revegetation days in partnership with Quiksilver, dune restoration at Anglesea with ANGAIR, and assisting landowners with rewilding programs in Freshwater Creek. Part of the SCIPN (Surf Coast and Inland Plains Network) Landcare network. Organises field trips and speakers throughout the year as well as hands-on working bees. More focused on farmland and inland waterways than the coastal groups above — different but complementary. Good for families with kids interested in farming and land stewardship.', 'https://scipn.com.au/', 3, 'Check scipn.com.au for current events and working bees. Annual rabbit program and field trips scheduled throughout the year.', '{"dry-trails"}', -38.3364, 144.3239, 'day', 'Research', true),
  (131, 'Marine & Freshwater Discovery Centre – Queenscliff', 'museum', '{"marine","ocean","education","kids","family","snorkelling","rockpool","queenscliff","science","aquarium"}', '{"all-ages"}', 'Cheap', 'Queenscliff', 55, '{"any"}', 'half-day', 'One of the best family education destinations in the region — run by the Victorian Fisheries Authority on the narrows between Swan Bay and Port Phillip Bay in Queenscliff. The building itself is remarkable: an award-winning 6-star sustainable design with a turf roof that rises out of its own constructed wetland, overlooking the World Heritage-listed Swan Bay. Facilities include a visitor aquarium and touch tank with local marine life, a student lab with microscopes and seawater tables, plus access to surrounding marine habitats for hands-on field activities: rock pool rambles, Swan Bay mudflat investigations, snorkelling, canoeing and boat trips in Port Phillip Bay. School holiday programs run in January and are popular — book well ahead. Open to school and community groups by booking; visitor aquarium open to general public. Worth combining with a wander around Queenscliff''s historic streets and lighthouse precinct.', 'https://vfa.vic.gov.au/education/marine-and-freshwater-discovery-centre', 5, 'On the narrows, Queenscliff. Run by Victorian Fisheries Authority. School/group programs by booking. Holiday programs in January — join mailing list via marine.discovery@vfa.vic.gov.au. Visitor aquarium open to public.', '{"good-in-rain"}', -38.2734, 144.6689, 'day', 'Research', true),
  (132, 'Repair Cafe Bellarine – Ocean Grove', 'community', '{"repair","sustainability","community","circular-economy","bellarine","ocean-grove","free","fix-it","zero-waste"}', '{"all-ages"}', 'Free', 'Ocean Grove', 38, '{"any"}', '~2hrs', 'The Bellarine''s answer to the Repair Cafe Surf Coast — a monthly fix-it event run by around 30 volunteers with diverse repair skills covering clothing and textiles, furniture, toys, electrical goods, computers, laptops, mobile phones and more. Operating since 2017, revived in 2024 after a COVID hiatus and now running monthly with strong community support. Bring your broken item, sit down with a volunteer repairer and work through the fix together — you don''t just drop things off and come back, you stay and learn. The Ocean Grove Men''s Shed handles more specialist bicycle rehabilitation. A brilliant companion to the Surf Coast Repair Cafe if you''re on the Bellarine side. Free to use, though donations welcome.', 'https://repaircafebellarine.org.au', 4, 'Third Sunday of every month, 12:30–3:30pm, Ocean Grove Neighbourhood House, 1 John Dory Drive, Ocean Grove. Check repaircafebellarine.org.au or Facebook for any date changes.', '{"good-in-rain"}', -38.2661, 144.5197, 'day', 'Research', true),
  (133, 'Spring Creek Horse Rides – Bellbrae', 'sport', '{"horse-riding","trail-ride","family","otways","national-park","bellbrae","all-abilities","kids","scenic"}', '{"all-ages"}', 'Moderate', 'Bellbrae', 10, '{"any"}', '1–2hrs', 'One of the best activity operators on the Surf Coast — trail rides through the Great Otway National Park from a 60-hectare property at Bellbrae, just 10 minutes from Jan Juc. Rides range from a 1-hour gentle intro walk (kids 9+, perfect for first-timers) through to 1.5hr and 2hr trotting rides into the national park, a 2.5hr ride along the Anglesea River all the way into Anglesea town, and full-day options. Pony patrol rides available for little ones aged 2–8. Horses are well-matched to rider ability — beginners genuinely welcomed, not just tolerated. The Spring Creek Valley backdrop through Otway bush is spectacular and feels a world away from the coast. They also offer cabin accommodation on-site if you want to make a weekend of it. Booking essential — minimum 2 riders per ride, arrive 15 mins early.', 'https://www.springcreekhorserides.com.au', 5, 'Bellbrae, off Great Ocean Road. Book online — essential, don''t just show up. 1hr from $95, 2hr from $130 approx. Check website for current pricing. Cabins available for overnight stays.', '{"dry-trails"}', -38.3693, 144.2445, 'day', 'Research', true),
  (134, 'Otways Indigenous Nursery – Aireys Inlet', 'nursery', '{"nursery","indigenous-plants","native","revegetation","garden","sustainability","aireys-inlet","surf-coast"}', '{"adults"}', 'Cheap', 'Aireys Inlet', 28, '{"any"}', '< 1hr', 'The go-to indigenous plant nursery for anyone on the Surf Coast wanting to garden with plants that actually belong here. Operating since 1990 on Wadawurrung Country in Aireys Inlet, they grow over 150 species of plants found naturally between Torquay and Cape Otway — all propagated from locally collected seed and cuttings, so they''re perfectly matched to local soils and conditions. Range covers everything from groundcovers and grasses to advanced trees. The team genuinely knows the ecology — great for advice on what to plant where, especially for dune-adjacent or heathland gardens. Also mentioned as a key supplier to GORCC, ANGAIR and other coastal revegetation projects. A worthwhile stop any time you''re heading down to Aireys Inlet or Lorne — pick up some plants and grab a coffee at the Aireys pub or bakery while you''re there.', 'https://www.otwaysindigenousnursery.com.au', 5, '6 Gilbert Street, Aireys Inlet. Open by appointment — call 0417 154 413 or check website/Instagram before visiting. Gift vouchers available.', '{"dry-ground"}', -38.4611, 144.1018, 'day', 'Research', true),
  (135, 'genU Community Nurseries – Geelong', 'nursery', '{"nursery","indigenous-plants","native","geelong","bellarine","otways","community","disability","social-enterprise"}', '{"all-ages"}', 'Cheap', 'Geelong', 21, '{"any"}', '< 1hr', 'A social enterprise nursery run by genU (formerly Karingal) growing indigenous plants from the Geelong, Bellarine and Otways regions — and creating meaningful employment for people living with disabilities in the process. All plants are propagated on-site with a focus on local provenance for revegetation, farm windbreaks, agroforestry and home gardens. Open to the public weekdays — a relaxed, friendly place to browse a solid range of Bellarine and Otway region natives at very reasonable prices. If you''re planting out a garden in Torquay or Jan Juc and want plants suited to local coastal conditions, this is a good starting point. Your purchase also directly supports community employment — a rare double win.', 'https://www.genu.org.au/community-nurseries/', 4, 'Geelong location — check genu.org.au for current address and weekday opening hours. Also a Colac location. Good range of Bellarine and Otway provenance plants.', '{"dry-ground"}', -38.1518, 144.3631, 'day', 'Research', true),
  (136, 'Nick''s Natives – Wallington', 'nursery', '{"nursery","indigenous-plants","native","bellarine","wallington","provenance","revegetation","surf-coast"}', '{"adults"}', 'Cheap', 'Wallington', 28, '{"any"}', '< 1hr', 'A specialist grower of Bellarine Peninsula and Surf Coast indigenous plants run by Nick from his property in Wallington. As of today only 5% of the Bellarine''s native vegetation remains — Nick''s mission is directly about reversing that, one garden at a time. All plants grown from locally collected seed of local provenance — meaning they''re genetically matched to the peninsula, not just ''native to Australia'' in the generic sense. Covers a wide range from tubes to advanced stock; wholesale list available on the website. Nursery visits by appointment or when advertised open days are posted; online store ships to most of Australia. Perfect for anyone on the Bellarine side wanting to convert a lawn to native garden — Nick will also advise on what species suit your specific conditions.', 'https://nicksnatives.com', 4, 'Wallington. Open by appointment or advertised open days — check nicksnatives.com or Facebook. Web store available for online orders. Wholesale list downloadable from website.', '{"dry-ground"}', -38.2243, 144.4762, 'day', 'Research', true),
  (137, 'Queenscliffe Indigenous Nursery', 'nursery', '{"nursery","indigenous-plants","native","queenscliff","bellarine","swan-bay","community","volunteer-run"}', '{"all-ages"}', 'Cheap', 'Queenscliff', 55, '{"any"}', '< 1hr', 'A community-run indigenous nursery operated by the Swan Bay Environment Association, growing plants indigenous specifically to Swan Bay and the Bellarine Peninsula. This level of local provenance specificity matters — planting the right genetic stock helps maintain the unique character of the coastal towns and supports local wildlife. Open regularly (Mon, Tue, Thu 9am–3pm plus last Sunday of month 10am–1pm) at the Bellarine Secondary College grounds in Drysdale. Prices are community-friendly and the knowledge on hand is deep. Worth combining with a Queenscliff visit — grab plants on the way home. Supports the broader Swan Bay conservation network.', 'https://swanbayenvironment.org.au/queenscliffe-indigenous-nursery/', 4, 'Bellarine Secondary College, Drysdale (despite the ''Queenscliffe'' name). Open Mon, Tue, Thu 9am–3pm + last Sunday of month 10am–1pm. Check swanbayenvironment.org.au to confirm.', '{"dry-ground"}', -38.2718, 144.6543, 'day', 'Research', true),
  (138, 'ANGAIR Plant Propagation Centre – Anglesea', 'nursery', '{"nursery","indigenous-plants","native","anglesea","angair","conservation","community","volunteer-run"}', '{"all-ages"}', 'Cheap', 'Anglesea', 20, '{"any"}', '< 1hr', 'ANGAIR''s dedicated plant propagation centre at the Anglesea Community Precinct — opened after 12+ years operating from private properties. Grows indigenous plants specifically suited to the Anglesea and Aireys Inlet area, with proceeds funding ANGAIR''s ongoing conservation work protecting the internationally significant Anglesea heathlands. If you''re gardening anywhere between Torquay and Lorne, this is about as locally provenant as plants get — grown from seed collected right in the area. Also a good reason to visit the Anglesea Community Precinct, which is a genuine hub of local sustainability activity. Check ahead for opening times.', 'https://angair.org.au', 4, 'Anglesea Community Precinct, Anglesea. Check angair.org.au for current opening times — hours vary. ANGAIR office at 3C McMillan St Anglesea.', '{"dry-ground"}', -38.4044, 144.1829, 'day', 'Research', true),
  (139, 'Geelong Native Plants – Mt Duneed', 'nursery', '{"nursery","native-plants","coastal","surf-coast","geelong","indigenous","garden","local"}', '{"all-ages"}', 'Cheap', 'Mt Duneed', 8, '{"any"}', '< 1hr', 'The closest native plant nursery to Jan Juc — just 8km up the Surf Coast Highway at Mt Duneed. Owner Christine Russell has 30+ years of horticulture experience and specialises in coastal and bush garden plants suited specifically to the Geelong and Surf Coast region. Range covers native grasses, trees, shrubs and groundcovers designed to thrive in salty, windy, coastal conditions with minimal watering once established. Open most days so easy to pop in without booking. The ideal first stop if you''re converting a garden in Jan Juc, Torquay or surrounds to low-maintenance natives — Christine will help you work out what suits your soil and aspect. Delivery available to Surf Coast Shire and Geelong.', 'https://www.geelongnativeplants.com.au', 4, '645 Surf Coast Highway, Mt Duneed. Open Wed–Sun 8am–4pm, or by appointment. Ph: 0434 948 866. Email: geelongnativeplants@gmail.com. Delivery available locally.', '{"dry-ground"}', -38.2385, 144.3196, 'day', 'Research', true),
  (140, 'Bellarine Landcare Nursery – Drysdale', 'nursery', '{"nursery","indigenous-plants","native","bellarine","drysdale","landcare","community","revegetation"}', '{"all-ages"}', 'Cheap', 'Drysdale', 35, '{"any"}', '< 1hr', 'The Bellarine Peninsula''s community landcare nursery, run in partnership with Bellarine Secondary College. Grows indigenous plants of Bellarine Peninsula provenance — species that historically occurred on this specific piece of the planet, not just generically ''Australian native''. Great range for anyone gardening on the Bellarine or wanting to support local revegetation work. Accessible most of the working week and one Sunday a month, so easy to combine with a Bellarine day trip. Purchasing from here directly supports both the landcare network and the school students who grow and propagate the plants as part of their program.', 'https://bellarinelandcare.org.au/activities/indigenous-nursery', 4, 'Belchers Road, Drysdale. Open Mon, Tue, Thu 9am–3pm + last Sunday of month 10am–1pm. Ph: 0439 392 369. Email: landcarenursery@bigpond.com.', '{"dry-ground"}', -38.1744, 144.5706, 'day', 'Research', true),
  (141, 'Anglesea Paddle Boat & Canoe Hire', 'water', '{"kayak","canoe","paddle-boat","family","anglesea","river","kids","wildlife","flat-water"}', '{"all-ages"}', 'Cheap', 'Anglesea', 20, '{"spring","summer","autumn"}', '1–2hrs', 'One of the classic Jan Juc family day trips — hire a canoe or paddle boat and drift down the beautiful Anglesea River past Coogoorah Park. The riverside is famous for its eastern grey kangaroos grazing right on the banks, making this a genuinely wildlife-rich paddle without having to go anywhere exotic. Canoes take 2 adults + a small child; paddle boats and aqua bikes also available. The river is calm and protected — perfect for kids who''ve never paddled before. About an hour downstream with the usual tailwind, but allow time coming back. Located right beside the Anglesea River bridge on the Great Ocean Road. Go Ride A Wave next door also hires sit-on-top kayaks if you want ocean-style boats.', 'https://www.angleseapaddleandcanoe.com', 5, 'Riverbank opposite 105 Great Ocean Road, Anglesea (next to the bridge). Seasonal — check they''re open before driving down. Canoes ~$35/hr. Cash preferred. No booking required.', '{"calm-sea"}', -38.4062, 144.184, 'day', 'Research', true),
  (142, 'Kayaking the Anglesea River – Go Ride A Wave', 'water', '{"kayak","hire","anglesea","river","sit-on-top","family","beginner","surf-coast"}', '{"all-ages"}', 'Cheap', 'Anglesea', 20, '{"spring","summer","autumn"}', '1–2hrs', 'Go Ride A Wave''s Anglesea shop hires out sit-on-top double kayaks (Ocean Kayak Malibu 2s) for use on the Anglesea River and at Point Roadknight beach. The Malibu 2 is a super stable, beginner-friendly boat — it can be paddled solo, as a double, or with a small child in the centre seat. The Anglesea River runs through Coogoorah Park, offering the same kangaroo-on-the-banks experience as the paddle boat hire next door, with a slightly more kayak-style feel. Point Roadknight is a sheltered bay that''s excellent for calm-water kayaking. Call ahead to confirm availability — the fleet is popular in summer. Same shop also does surf lessons and SUP hire.', 'https://gorideawave.com.au/location/anglesea/', 4, 'Great Ocean Road, Anglesea (opposite main beach). Ph: 1300 132 441. Call ahead to confirm kayak availability. Also hires surfboards, bodyboards and SUPs.', '{"calm-sea"}', -38.4041, 144.1843, 'day', 'Research', true),
  (143, 'Paddle Life – Barwon River, Barwon Heads', 'water', '{"kayak","canoe","sup","stand-up-paddleboard","barwon-heads","river","hire","family","estuary","coaching"}', '{"all-ages"}', 'Cheap', 'Barwon Heads', 28, '{"any"}', '1–2hrs', 'Hire kayaks, canoes or stand-up paddleboards on the Barwon River estuary at Barwon Heads — one of the most scenic paddles in the region. The 19km river estuary runs from Lake Connewarre to the sea, flanked by mangroves, sandbars and birdlife. Paddle Life offers half and full-day hire, lessons for beginners and performance coaching for more serious paddlers. The protected estuary is ideal for families — calm water with the occasional river dolphin sighting as a bonus. For a memorable route, paddle upstream through the mangroves toward the bridge and back. Barwon Heads is also a beautiful town in its own right — combine with lunch at one of the cafes on Jetty Road.', 'https://www.paddlelifebarwonheads.com', 4, 'Barwon Heads. Check paddlelifebarwonheads.com for current hire rates and session availability. Lessons available for all levels including beginners.', '{"calm-sea","low-wind"}', -38.2798, 144.4964, 'day', 'Research', true),
  (144, 'Barwon River – Self-Guided Kayak or SUP', 'water', '{"kayak","sup","barwon-river","free","self-guided","ocean-grove","barwon-heads","estuary","wildlife","birdwatching"}', '{"teens","adults"}', 'Free', 'Ocean Grove / Barwon Heads', 28, '{"spring","summer","autumn"}', 'half-day', 'If you have your own kayak, canoe or SUP, the Barwon River estuary is one of the best free paddles in the region. The 19km stretch from Lake Connewarre to Barwon Heads is tidal, calm and rich with birdlife — black swans, pelicans, herons and the occasional dolphin. Launch points include the Barwon Heads boat ramp, the Ocean Grove foreshore, or behind Riverview Caravan Park. Paddle upstream from Barwon Heads toward Lake Connewarre for a genuine waterway wilderness experience — the mangroves and reed beds make it feel completely remote despite being 10 mins from Ocean Grove. Tide and wind matter — best to paddle at or near high tide, and ideally with little wind. Check the Barwon Heads tide chart before heading out.', 'https://www.google.com/maps/search/Barwon+Heads+boat+ramp+Victoria', 4, 'Launch from Barwon Heads boat ramp or Ocean Grove foreshore. Tidal — plan around high tide. Wind can make the return leg hard. No hire on-site; bring your own craft or use Paddle Life nearby.', '{"calm-sea","low-wind"}', -38.2773, 144.4963, 'day', 'Research', true),
  (145, 'Lake Elizabeth Platypus Canoe Tour – Otway Eco Tours', 'water', '{"kayak","canoe","platypus","wildlife","otways","lake-elizabeth","forrest","night","glow-worms","family"}', '{"kids","teens","adults"}', 'Splurge', 'Forrest (Otways)', 98, '{"any"}', 'half-day', 'One of the most extraordinary nature experiences within range — a guided canoe tour on the hauntingly beautiful Lake Elizabeth, deep in the Otways near Forrest. The lake was formed by a landslide in the 1950s, leaving ghostly dead tree trunks rising from the still, dark water surrounded by towering mountain ash and tree ferns. Otway Eco Tours has run guided platypus canoe tours here for 20+ years with a remarkable 95% sighting success rate. Tours run at dawn or dusk; the 1km forest walk to the lake passes koalas in the trees, and the dusk tour adds glow worms on the walk back. Small groups (max 7), guided by an expert ecologist. Kids from about 6–7 onwards will handle the walk and be genuinely awed. At 98km it''s the outer edge of the database range — best done as part of a Forrest or Great Ocean Road overnight trip. Worth it.', 'https://platypustours.net.au', 5, 'Meet at Forrest Brewing Company, 26 Grant Street, Forrest. Tours ~2.5hrs. Adults ~$85, children ~$50. Book via platypustours.net.au. Tours run most of the year except mid-July to mid-September (platypus breeding season). Dawn or dusk options.', '{"calm-sea","low-wind"}', -38.5421, 143.7476, 'day', 'Research', true),
  (146, 'Kennett River Koala Walk (Grey River Road)', 'nature', '{"koalas","wildlife","family","free","great-ocean-road","nature","king-parrots","grey-river-road"}', '{"all-ages"}', 'Free', 'Kennett River', 98, '{"any"}', '< 1hr', 'One of the best places in Australia to see wild koalas — and it''s free. Grey River Road at Kennett River (halfway between Lorne and Apollo Bay) is lined with blue gums that a large colony of koalas call home, and they''re remarkably easy to spot. Look for the round grey blobs tucked in the forks of trees — other visitors staring upward is usually the giveaway. Best in the first 300m–1km from the Kafe Koala carpark. The same spot is famous for rainbow lorikeets, king parrots and cockatoos that come down to feed near the cafe. Early morning or late afternoon gives the best chance of seeing koalas moving and eating rather than sleeping. Avoid middle-of-day tourist bus crowds if you can. The road is technically driveable but walking slowly is far better. Combine with a swim at the Kennett River beach and a coffee at Kafe Koala. A near-perfect Great Ocean Road day trip stop for any age.', 'https://www.google.com/maps/search/Grey+River+Road+Kennett+River+Victoria', 5, 'Grey River Road, Kennett River — starts directly opposite Kafe Koala. Free, open all year. Kafe Koala open daily 7am–7pm. Toilets at the car park. Don''t feed the wildlife. At 98km this is at the outer edge of range — best as part of a GOR day trip.', '{"any-weather"}', -38.6581, 143.7214, 'day', 'Research', true),
  (147, 'Jirrahlinga Koala & Wildlife Sanctuary – Barwon Heads', 'nature', '{"koalas","wildlife","sanctuary","family","kids","barwon-heads","bellarine","animals","close-encounter"}', '{"all-ages"}', 'Moderate', 'Barwon Heads', 28, '{"any"}', 'half-day', 'A genuine wildlife sanctuary — not a zoo — set on 5 acres at the northern edge of Barwon Heads. Jirrahlinga (Aboriginal for ''seek a home for a kangaroo'') was established in 1975, gained national attention rescuing burnt animals after Ash Wednesday in 1983, and has been caring for injured native wildlife ever since. Home to koalas, kangaroos, wombats, wallabies, pademelons, emus, dingoes, reptiles, cockatoos, turtles, owls and more. Daily animal encounter sessions let you get genuinely close — think holding a snake, watching a wombat play, or a koala snoozing an arm''s length away. Not your typical tourist attraction; it''s intimate, educational and small. A particular highlight for younger kids who want to be close to animals rather than watching from behind glass. Also runs programs specifically for people with disabilities and special needs — an unusually inclusive space.', 'https://www.jirrahlinga.com.au', 4, 'Taits Road, Barwon Heads. Open Thu–Tue 10am–4pm, closed Wednesdays and total fire ban days. Ph: (03) 5254 2484. Check website for current entry prices and any booking requirements.', '{"any-weather"}', -38.2699, 144.5006, 'day', 'Research', true),
  (148, 'Ocean Grove Nature Reserve – Koalas & Woodland Walk', 'nature', '{"koalas","wildlife","nature-reserve","bellarine","ocean-grove","family","birdwatching","free","koala"}', '{"all-ages"}', 'Free', 'Ocean Grove', 38, '{"any"}', '< 1hr', 'The only remaining substantial native woodland on the Bellarine Peninsula — 143 hectares of she-oak, tea-tree, banksia and wattle at the northern edge of Ocean Grove. Home to a resident koala community, a population of wallabies, and the remarkable ant blue butterfly (only discovered in the 20th century, found nowhere else). Two walking tracks: the 3km Discovery Trail (Banksia Trail) and the 1.5km Wallaby Trail, plus a bird hide walk via the north track (~40 minutes). Go slowly and scan the forks of trees for koalas — they''re resident but not guaranteed. Best in early morning when birdsong is at its peak. Gate closes at 5pm. A genuinely special piece of ecology that most people don''t know exists on the Bellarine, and well worth combining with a wander through Ocean Grove or a coffee on The Terrace.', 'https://www.google.com/maps/search/Ocean+Grove+Nature+Reserve+Victoria', 4, 'Grubb Road, Ocean Grove (northern edge of town). Gate closes 5pm. Free entry. Dogs not permitted in the reserve. Two trails: Banksia Trail (3km) and Wallaby Trail (1.5km).', '{"dry-trails"}', -38.249, 144.5, 'day', 'Research', true),
  (149, 'Coogoorah Park – Anglesea River Kangaroos', 'nature', '{"kangaroos","wildlife","family","free","anglesea","river","birdwatching","picnic","walk","kids"}', '{"all-ages"}', 'Free', 'Anglesea', 20, '{"any"}', '< 1hr', 'A little-publicised but brilliant family spot — Coogoorah Park runs along the Anglesea River with a network of boardwalks through riverine bushland where eastern grey kangaroos graze right on the banks, often within a few metres of the path. The water is famously crystal clear blue, the boardwalks are accessible and well-kept, and there''s a great playground for younger kids. Perfect for combining with canoe hire next door, or just as a gentle 30–45 minute riverside wander before coffee in town. Ducks, bream (fishable from the bank), herons and cockatoos are regulars. Free BBQ facilities and picnic areas make it a solid full-morning option. The kangaroos here are used to people but are still wild — give them space and they''ll often come surprisingly close. Early morning is quietest and has the best wildlife activity.', 'https://www.google.com/maps/search/Coogoorah+Park+Anglesea+Victoria', 4, 'Off Coogoorah Park Road, Anglesea — follow signs from the main street toward the river. Free entry. Playground, BBQs and toilets on site. Accessible boardwalks.', '{"dry-ground"}', -38.4042, 144.1798, 'day', 'Research', true),
  (150, 'Anglesea Heath – Wildflower & Echidna Spotting', 'nature', '{"heathland","wildflowers","echidna","nature","anglesea","spring","biodiversity","free","walk","birdwatching"}', '{"all-ages"}', 'Free', 'Anglesea', 20, '{"spring"}', '< 1hr', 'The Anglesea heathlands are internationally significant for their biodiversity — over 100 species of orchid bloom here in spring, and the coastal heath between Anglesea and Aireys Inlet is one of the most species-rich plant communities in Victoria. In spring (August–October) the heathland explodes into colour: spider orchids, sun orchids, wattles, banksias and heath flowers at their peak. Echidnas are commonly spotted digging for ants along the sandy coastal paths — look carefully near low shrubs and sandy patches in the early morning. The Anglesea Bushland Reserve and the heathland sections of the Surf Coast Walk are the best access points. ANGAIR also runs guided wildflower walks in September. Worth a special spring visit — the transformation from bare heathland to wildflower display is genuinely spectacular and almost unknown outside the local community.', 'https://www.google.com/maps/search/Anglesea+Bushland+Reserve+Victoria', 4, 'Access via Anglesea Bushland Reserve or Surf Coast Walk between Anglesea and Aireys Inlet. Best August–October for wildflowers. ANGAIR runs guided walks in September — check angair.org.au.', '{"dry-trails","warm"}', -38.4203, 144.1578, 'day', 'Research', true),
  (151, 'Hooded Plover Spotting – Surf Coast Beaches', 'nature', '{"birdwatching","hooded-plover","conservation","beach","wildlife","surf-coast","family","free","nature"}', '{"all-ages"}', 'Free', 'Surf Coast wide', 0, '{"any"}', '< 1hr', 'One of Victoria''s most vulnerable shorebirds nests right on Surf Coast beaches — the hooded plover is a small black, white and red bird that lives and breeds on the sand itself, making it highly vulnerable to dogs, foot traffic and vehicles. Look for the orange nesting exclusion signs on beaches between August and March — these mark active nests, and spotting the bird itself is a genuine thrill. Jan Juc, Bells Beach and Fairhaven are known hooded plover beaches. The Friends of Hooded Plover Bellarine and BirdLife Australia both run volunteer monitoring programs if you want to get more involved. A lovely way to turn a beach walk into something more purposeful with kids — teaching them to watch where they walk and why it matters.', 'https://www.google.com/maps/search/Jan+Juc+Beach+Victoria', 4, 'Present on beaches across the Surf Coast year-round; nesting August–March. Respect orange exclusion signs — don''t approach active nests. Dogs must be on-lead near nesting zones. Check BirdLife Australia for volunteer monitoring info.', '{"low-tide"}', -38.3682, 144.296, 'day', 'Research', true),
  (152, 'Narana / Wathaurong Booln Booln Cultural Centre', 'cultural', '{"indigenous","aboriginal","wadawurrung","wathaurong","culture","family","art-gallery","bush-tucker","education","reconciliation","first-nations"}', '{"all-ages"}', 'Free', 'Grovedale', 12, '{"any"}', 'half-day', 'The most important First Nations cultural destination in the region — and it''s right on the Surf Coast Highway, 12km from Jan Juc. The Wathaurong Booln Booln Cultural Centre (formerly and still known as Narana — ''to deeply listen and understand'') is a not-for-profit Aboriginal Cultural Centre on Wadawurrung Country, offering free entry and a genuinely welcoming atmosphere for families, visitors and locals alike. ''Booln Booln'' means lyrebird — a speaker of all languages — reflecting the many mobs that make up the Wathaurong community. Visit for: guided cultural experiences delivered by Wadawurrung Cultural Interpreters; Dreaming stories; connection to Country through songlines; tool and artefact displays; boomerang throwing; feeding the resident emus and wallabies; and a substantial art gallery featuring Indigenous artists from across Australia. The Booln Booln Café serves bush tucker-inspired food — kangaroo ragu with Kakadu plum, lemon myrtle chicken, wattleseed pastries — made by a Michelin-trained pastry chef. This is a critically important stop for any family wanting to understand that they are living and playing on Wadawurrung Country — land cared for by the Wadawurrung people for at least 60,000 years.', 'https://www.narana.com.au', 5, '410 Surf Coast Highway, Grovedale (on the way to Torquay). Free entry; guided programs at moderate cost — book via website or ph (03) 5241 5700. Open Mon–Fri 9am–5pm, Sat 9am–4pm. Café Thu–Sun 9am–3pm. Check website as hours and branding continue to evolve.', '{"good-in-rain"}', -38.196, 144.3139, 'day', 'Research', true),
  (153, 'Point Addis Koorie Cultural Walk', 'cultural', '{"indigenous","aboriginal","wadawurrung","wathaurong","cultural-walk","interpretive","koorie","surf-coast","family","point-addis","first-nations"}', '{"all-ages"}', 'Free', 'Point Addis', 7, '{"any"}', '< 1hr', 'A 2km return walk along the Surf Coast Walk that is formally dedicated to sharing Wadawurrung knowledge of Country. Starting from the Point Addis car park, interpretive signage along the clifftop trail explains the deep Wadawurrung connection to this coastline — including shell middens, the use of ochre from the vivid cliffs, traditional fishing and foraging practices, and the significance of specific plants and animals in Wadawurrung culture and law. The walk passes through heathland above the ochre-and-sandstone cliffs of Point Addis Marine National Park, with sweeping views over Addiscot Beach and south toward Bells Beach. The cliffs here have been a place of significance for the Wadawurrung for tens of thousands of years — the walk invites visitors to understand the land they''re standing on, not just admire the view from it. An ideal companion to a visit to Narana, and a way to make Point Addis much more than just a surf spot. Short, easy, and genuinely rich in content.', 'https://visitgreatoceanroad.org.au/angleseaadventure/activities/point-addis-koorie-cultural-walk/', 5, 'Start from Point Addis car park, Point Addis Road, Mt Duneed. 2km return, well-formed track with short steep sections and steps. Free. No facilities at the car park — bring water.', '{"dry-ground"}', -38.3975, 144.2534, 'day', 'Research', true),
  (154, 'Wadawurrung Country – Understanding Where You Are', 'cultural', '{"indigenous","aboriginal","wadawurrung","wathaurong","education","country","reconciliation","culture","online","family","first-nations"}', '{"all-ages"}', 'Free', 'Surf Coast wide', 0, '{"any"}', '< 1hr', 'Jan Juc, Torquay, Anglesea, Aireys Inlet, the Bellarine Peninsula — all of it is Wadawurrung Country. The Wadawurrung people of the Kulin Nation have lived on, cared for and governed this land and sea for at least 60,000 years. That connection never stopped. The Wadawurrung Traditional Owners Aboriginal Corporation (WTOAC), registered since 1998, is the peak body speaking for Wadawurrung Country. They offer cultural education sessions, on-Country immersive experiences, and are the custodians of cultural knowledge for the entire Surf Coast, Geelong and Ballarat region. As a starting point: their website (wadawurrung.org.au) introduces the Country, language and people. Narana/Wathaurong Booln Booln Cultural Centre (ID nearby) is the most accessible in-person cultural destination. The ''Journey on Wadawurrung Country'' immersive exhibition — with Elders'' portraits, oral histories and Country soundscapes — periodically tours the region and is free when it appears; watch for it at Grant Pavilion Torquay, The Potato Shed Drysdale, and Geelong Performing Arts Centre. Spending an hour with these resources before your next walk, surf or trip down the Great Ocean Road will permanently change how you see the place.', 'https://www.wadawurrung.org.au', 5, 'Online starting point: wadawurrung.org.au. Cultural education and on-Country experiences available by booking via WTOAC. Watch for the ''Journey on Wadawurrung Country'' touring exhibition — free when it appears locally.', '{"any-weather"}', -38.3655, 144.2978, 'day', 'Research', true),
  (155, 'You Yangs Regional Park – Wurdi Youang (Wadawurrung Country)', 'cultural', '{"you-yangs","wadawurrung","aboriginal","indigenous","walking","granite","scenic","cultural","birds","kangaroos","first-nations"}', '{"all-ages"}', 'Cheap', 'Little River (You Yangs)', 47, '{"any"}', 'half-day', 'The You Yangs — Wurdi Youang in Wadawurrung language, meaning ''big hill in the middle of a plain'' — are a dramatic series of granite ridges rising from the Werribee Plain, deeply significant in Wadawurrung songlines and cultural history. Walking these ridges, you''re walking on Country that has been understood, named and cared for by the Wadawurrung for tens of thousands of years. The park offers excellent bushwalking (Flinders Peak at 352m gives views across Port Phillip Bay to the Dandenongs), mountain biking, rock climbing and birdwatching. Koalas, kangaroos, echidnas and wedge-tailed eagles are regularly sighted. Close to the You Yangs is the Wurdi Youang stone arrangement — an egg-shaped ring of around 100 basalt stones created by the Wadawurrung people, believed to be the world''s oldest astronomical observatory, aligned to mark the solstices and equinoxes. The stone arrangement is on private Wadawurrung-owned land; the custodians have deliberately kept the exact location private to protect it. It is not open to casual visitors — respect this. Cultural access is available through the Wadawurrung Traditional Owners Aboriginal Corporation (wadawurrung.org.au). The You Yangs walking trails are open to all and are a worthwhile half-day from Jan Juc.', 'https://www.parks.vic.gov.au/places-to-see/parks/you-yangs-regional-park', 4, 'Off Princes Freeway, Little River. Parks Victoria entry fee applies. Flinders Peak walk is the most popular. Trail map at parks.vic.gov.au. Note: the Wurdi Youang stone arrangement is on private Wadawurrung land and is NOT open to casual visitors — access only through WTOAC.', '{"dry-trails"}', -37.9249, 144.458, 'day', 'Research', true),
  (156, 'Split Point Lighthouse – Wathaurung Country Discovery Trail', 'cultural', '{"lighthouse","aireys-inlet","wadawurrung","wathaurong","cultural","interpretive-trail","family","coastal","historic","first-nations"}', '{"all-ages"}', 'Cheap', 'Aireys Inlet', 30, '{"any"}', '< 1hr', 'The Split Point Lighthouse walk doubles as a cultural discovery trail across traditional Wathaurung Country, with interpretive signage at several viewing platforms marking the ancient tribal boundary at the western reach of the Surf Coast Walk. The trail acknowledges the Wadawurrung people''s deep relationship with this headland and the sea below — a coastline used for fishing, ceremony and shelter for millennia. The 1891 lighthouse is the most photographed on the Great Ocean Road, and the headland gives spectacular views back toward Point Addis and east toward Torquay. Tours of the lighthouse interior are available for a small fee. The walk is well-formed and narrow — good for all ages. Listen for Rufous Bristlebirds in the coastal scrub; look for tiny marsupials scurrying in the low scrubland. A great way to combine landscape, history and cultural context in a single 1–2hr outing.', 'https://www.splitpointlighthouse.com.au', 4, 'Boundary Road, Aireys Inlet. Free to walk to; lighthouse tours available for a small fee. Well-formed narrow track. Check splitpointlighthouse.com.au for tour times.', '{"dry-ground"}', -38.4607, 144.1032, 'day', 'Research', true),
  (157, 'Gabby (Bass Yabby) Pumping', 'nature', '{"fishing","kids","low-tide","yabby","cosy-corner","bait","beach","free","family"}', '{"all-ages"}', 'Free', 'Torquay / Cosy Corner', 4, '{"any"}', '< 1hr', 'Pumping for bass yabbies (gabbies) at low tide is one of those simple, absorbing activities that kids get completely hooked on — and the yabbies make excellent fishing bait. All you need is a yabby pump (also called a tube pump or bait pump), a bucket with water, and a low tide. Push the pump into wet sand near the water''s edge where you can see small holes or bubbles, pull the handle sharply, and deposit the core on the sand. A gabby — a small pale crustacean — will wriggle out if you''re in the right spot. Cosy Corner in Torquay is one of the best local spots: the calm, sheltered bay means the sand stays accessible and the water stays clear. Also worth trying at the Anglesea River mouth, Jan Juc creek mouth at low tide, and the Barwon River estuary at Barwon Heads. The gabbies go straight into your bait bucket with sea water — keep them cool and aerated and they''ll stay alive for hours. Even if you''re not fishing, kids will happily hunt and release for an entire low tide window. Yabby pumps are available at Torquay fishing and hardware stores for around $20–30.', 'https://www.google.com/maps?q=-38.3319,144.3243', 4, 'Needs a low tide window — check tide times before going. Cosy Corner car park off The Esplanade. Yabby pumps from Torquay fishing/hardware stores. Also good at Anglesea River mouth and Barwon Heads estuary.', '{"low-tide"}', -38.3319, 144.3243, 'day', 'Research', true),
  (158, 'iNaturalist – Record Local Biodiversity', 'nature', '{"citizen-science","biodiversity","inaturalist","plants","animals","fungi","insects","birds","marine","identification","app"}', '{"all-ages"}', 'Free', 'Anywhere – Surf Coast', 0, '{"any"}', 'open-ended', 'iNaturalist is the world''s most popular citizen science app for recording nature — photograph a plant, bird, insect, spider, fungi or marine creature and the community and AI help identify it. Every observation you submit goes into global biodiversity databases used by researchers and conservation managers. The Surf Coast has a rich, active iNaturalist community and a dedicated Great Southern BioBlitz project that runs each September. The Anglesea heathland, Jan Juc clifftops, Point Addis and the Otways are all exceptional spots for observations. Kids especially love the ID feedback loop — photo something, watch it get identified by experts within hours. No equipment needed beyond a phone.', 'https://www.inaturalist.org/projects/great-southern-bioblitz-umbrella', 5, 'Free app on iOS and Android. Create an account to track your observations. September = Great Southern BioBlitz — friendly competition to record the most species across the southern hemisphere.', '{"any-weather"}', -38.3401, 144.32, 'day', 'Research', true),
  (159, 'Aussie Backyard Bird Count', 'nature', '{"citizen-science","birds","birdlife-australia","bird-count","survey","annual","october","backyard","birdwatching"}', '{"all-ages"}', 'Free', 'Anywhere – your backyard or local patch', 0, '{"spring"}', '20 minutes', 'Each October, BirdLife Australia runs the Aussie Backyard Bird Count — 20 minutes, watching and counting birds from wherever you are. Submissions go into national population monitoring data. The Surf Coast has excellent bird diversity: the Anglesea heathland has White-throated Treecreeper, Gang-gang Cockatoo and Powerful Owl; the Jan Juc clifftops have Pacific Gulls, Peregrine Falcons and Short-tailed Shearwaters; the Anglesea River wetlands have herons and egrets. Students from Geelong Lutheran College have submitted checklists from the Torquay wetlands as part of the Great Ocean Road Coast Committee''s Coast Guardians program. The 2024 count received over 3.6 million bird sightings nationwide.', 'https://aussiebirdcount.org.au/', 4, 'Free app: ''Aussie Bird Count'' on iOS and Android. Runs one week in October each year — check website for exact dates. Can also do informal counts via eBird or Birdata year-round.', '{"dry-ground","low-wind"}', -38.32, 144.32, 'day', 'Research', true),
  (160, 'eBird & Birdata – Bird Surveys', 'nature', '{"citizen-science","birds","ebird","birdata","birdlife-australia","survey","birdwatching","hotspots","surf-coast"}', '{"all-ages"}', 'Free', 'Surf Coast – multiple hotspots', 0, '{"any"}', '30 min – half-day', 'Submit bird sightings year-round to eBird (Cornell Lab) or Birdata (BirdLife Australia) — both feed into scientific research used globally. The Surf Coast has several productive birding hotspots within easy reach: Anglesea River wetlands (herons, spoonbills, cormorants), Point Addis heathland (honeyeaters, eastern spinebills, scarlet robins), Jan Juc clifftops (seabirds, raptors), Torquay Surf Beach (terns, godwits in summer). A 20-minute 2-hectare survey submitted via Birdata contributes directly to BirdLife Australia''s State of Australian Birds project. The data is used to assess population trends and conservation status. Birdata''s 20-min survey format is the gold standard; eBird is easier and more flexible for casual observers.', 'https://birdata.birdlife.org.au/', 4, 'Birdata app: best for formal 20-min surveys. eBird app: better for casual birding lists. Both free on iOS and Android. No formal training needed — any sighting counts.', '{"dry-ground","low-wind"}', -38.32, 144.32, 'day', 'Research', true),
  (161, 'WhaleFace & Two Bays Whale Project – Report Whale Sightings', 'nature', '{"citizen-science","whale","southern-right-whale","humpback","whale-watching","photo-id","reporting","surf-coast","marine"}', '{"all-ages"}', 'Free', 'Surf Coast cliffs & headlands', 0, '{"winter","spring"}', 'as long as you''re watching', 'If you spot a whale from the Surf Coast cliffs — which is genuinely common between May and October — photograph it and submit the sighting. WhaleFace (run by DEECA) is the state government''s whale photo-ID platform for Southern Right Whales; the Two Bays Whale Project (via Dolphin Research Institute''s PodWatch app) covers humpbacks and other species across Victorian waters. Individual Southern Right Whales have been photographed from Anglesea, Lorne, Torquay and Point Addis and added to long-term catalogues. The best clifftop spots are Point Addis headland (8km), Teddy''s Lookout in Lorne (30km) and the Bells Beach cliff (2km). Binoculars help but are not required — whales are visible with the naked eye when close to shore.', 'https://www.dolphinresearch.org.au/research/report-sightings/', 5, 'WhaleFace: whaleface.swifft.net.au — for Southern Right Whale photo-ID. PodWatch app (Dolphin Research Institute): for all whale/dolphin species year-round. Both free. Peak season May–October. Report distressed whales: 1300 136 017.', '{"calm-sea"}', -38.38, 144.32, 'day', 'Research', true),
  (162, 'EstuaryWatch – Anglesea River', 'volunteering', '{"citizen-science","estuary","water-quality","monitoring","anglesea-river","corangamite-cma","volunteer","environment"}', '{"adults","teens"}', 'Free', 'Anglesea River Estuary', 15, '{"any"}', '2–3 hrs monthly', 'EstuaryWatch is a community-based citizen science program that monitors the health of Victorian estuaries. The Anglesea River is one of the 11 active monitoring sites in the Corangamite region — it has an Endangered Estuarine Wetland vegetation community and is habitat for vulnerable Eastern Great Egrets and Near Threatened Nankeen Night Herons. Monitoring teams of 4–6 volunteers visit monthly to collect water quality data (salinity, dissolved oxygen, turbidity, pH) and photograph estuary conditions. The data feeds directly into estuary management decisions by the Corangamite CMA and goes into a publicly accessible 30-year data archive. An excellent way to develop genuine environmental science skills while doing something that meaningfully matters.', 'https://www.vic.waterwatch.org.au/', 4, 'Contact Corangamite CMA on 1800 002 262 to join the Anglesea EstuaryWatch group. Volunteers meet monthly — timing flexible. Training provided. Equipment supplied.', '{"dry-ground"}', -38.4019, 144.1756, 'day', 'Research', true),
  (163, 'Reef Life Survey – Point Addis Marine National Park', 'nature', '{"citizen-science","reef","fish","marine","snorkelling","diving","point-addis","reef-life-survey","monitoring"}', '{"adults","teens"}', 'Free', 'Point Addis Marine National Park', 8, '{"summer","spring"}', 'half-day', 'Reef Life Survey is an international citizen science program where trained snorkellers and divers survey underwater fish, invertebrate and coral communities using standardised protocols. The data feeds directly into global marine biodiversity databases used in research and conservation policy. Point Addis Marine National Park (8km from Jan Juc) is one of the most accessible reef survey sites on the Victorian coast — kelp forests, reef fish, invertebrates and occasional cephalopods. Surveys require training; Reef Life Survey runs workshops for new volunteers. An excellent use of snorkelling skills that produces publishable-quality data. Results from Victorian reef sites have contributed to tracking southward range shifts in fish species under climate change.', 'https://reeflifesurvey.com/', 4, 'Training required before surveying — check reeflifesurvey.com for upcoming workshops. Snorkel surveys are beginner-accessible; dive surveys need SCUBA cert. Best conditions November–March. Wetsuit recommended year-round.', '{"calm-sea","low-tide"}', -38.4049, 144.12, 'day', 'Research', true),
  (164, 'Frog ID – Listen for Frogs at Night', 'night', '{"citizen-science","frogs","frog-id","audio","recording","night","app","anglesea-river","wetlands","monitoring"}', '{"all-ages"}', 'Free', 'Anglesea River, Jan Juc Creek, wetlands', 0, '{"spring","summer"}', '30 min – 1 hr', 'FrogID is the Australian Museum''s national citizen science project for recording frog calls. Go to a wetland, creek or dam at night — the Anglesea River, Jan Juc creek mouth, or any Otways creek — open the free FrogID app, and record what you hear for 3 minutes. The AI identifies the species from the calls and the data goes into national frog population monitoring. Australia has 7 threatened frog species, and citizen science recordings are critical for tracking their distribution. The Anglesea and Surf Coast area has spotted Marsh Frogs (Limnodynastes tasmaniensis), Bleating Tree Frogs (Litoria dentata) and potentially the endangered Growling Grass Frog (Litoria raniformis). Spring evenings after rain are the most productive. Kids find it genuinely magical.', 'https://www.frogid.net.au/', 4, 'Free app: FrogID on iOS and Android. Record a 3-minute audio clip near water. App identifies species from calls. Best in spring and after rain. Anglesea River boardwalk is an excellent survey site. No equipment beyond a phone.', '{"warm","good-in-rain"}', -38.33, 144.31, 'night', 'Research', true),
  (165, 'Redmap – Report Unusual Marine Species', 'nature', '{"citizen-science","marine","fish","climate-change","redmap","range-extension","snorkelling","diving","surf-coast"}', '{"adults","teens"}', 'Free', 'Surf Coast reefs & beaches', 0, '{"any"}', 'as you go', 'Redmap (Range Extension Database and Mapping project) tracks marine species appearing further south than their historical range — a direct indicator of ocean warming. If you spot an unusual fish, shark, ray, nudibranch or other marine creature while snorkelling, diving or rockpooling at Point Addis, Bells Beach or anywhere along the Surf Coast — photograph it and submit via the Redmap website or app. Redmap data has contributed to peer-reviewed research confirming that 77 marine species have extended their southern range along Australia''s east coast in the past decade. You don''t need to know what you''ve found — submit the photo and Redmap''s scientists will identify it. Any unusual sighting is worth reporting.', 'https://www.redmap.org.au/', 4, 'Free website and app. Photograph the species (in water is fine), note the location and depth, submit at redmap.org.au. Focus on species that seem unusual for the area — tropical fish, unusual invertebrates, nudibranches. No diving required — rockpool finds count.', '{"calm-sea"}', -38.38, 144.28, 'day', 'Research', true)
insert into events (id, name, type, starts_on, ends_on, time_text, recurrence, venue, location, km, cost, ages, artist, genre, description, ticket_url, info_url, conditions, date_confidence, added_by, verified) values
  (1, 'Live Music – Blackman''s Brewery', 'gig', date '2026-08-22', null, '7:30pm–10:30pm', 'weekly', 'Blackman''s Brewery', 'Torquay', 4, 'Free', '{"adults","teens"}', 'Local & touring acts', 'rock, folk, pop', 'Blackman''s hosts live music most Friday and Saturday nights in their courtyard. Mostly local and regional acts — folk, rock, surf-adjacent pop. The outdoor setting is brilliant in summer. Dog friendly. No cover charge but book a table if you want to eat.', null, 'https://blackmansbrewery.com.au/whats-on/', '{"dry-ground"}', 'high', 'Research', true),
  (2, 'Live Music – Aireys Inlet Hotel', 'gig', date '2026-08-23', null, '3pm–7pm', 'weekly', 'Aireys Inlet Hotel', 'Aireys Inlet', 18, 'Free', '{"adults","teens"}', 'Local & touring acts', 'rock, folk, country', 'The Aireys pub runs live music most Sunday afternoons on the outdoor deck. Classic pub rock, local singer-songwriters and occasional touring acts. The deck overlooks the bush — one of the better Sunday afternoon settings on the Surf Coast. Relaxed atmosphere, kids welcome in the beer garden.', null, 'https://www.facebook.com/aireyshotel/', '{"warm"}', 'high', 'Research', true),
  (3, 'Rip Curl Pro Bells Beach', 'sport-event', date '2027-04-12', date '2026-04-22', 'from 7am (heat-dependent)', 'annual', 'Bells Beach', 'Bells Beach / Torquay', 3, 'Free', '{"all-ages"}', null, null, 'The world''s longest-running professional surfing contest and a genuine Surf Coast institution. WSL Championship Tour stop. Watching from the clifftop is free and the atmosphere when there''s solid swell is electric — thousands of people, food trucks, surf industry presence. The exact run dates depend on swell — follow WSL and Rip Curl socials for heat schedules. One of the great free sporting spectacles in regional Victoria.', null, 'https://www.ripcurl.com/au/bells-beach/', '{"calm-sea"}', 'medium', 'Research', true),
  (4, 'Repair Café Surf Coast', 'community', date '2026-09-06', null, '10am–1pm', 'monthly', 'Rotates — check website', 'Surf Coast (rotates)', 10, 'Free', '{"all-ages"}', null, null, 'The Repair Café runs on the first Sunday of most months (not January, May or July) at rotating venues across the Surf Coast — Torquay, Anglesea, Lorne and surrounds. Bring broken items: clothes, electrical, furniture, bikes, jewellery. Volunteer repairers fix what they can for free. No booking required. A genuinely community-minded event that gets better every month as more skilled volunteers join.', null, 'https://repaircafesurfcoast.tech/', '{"good-in-rain"}', 'high', 'Research', true),
  (5, 'Torquay Farmers Market', 'market', date '2026-08-22', null, '8:30am–12:30pm', 'weekly', 'Fishermans Beach Reserve', 'Torquay', 4, 'Free', '{"all-ages"}', null, null, 'Every Saturday morning at Fishermans Beach Reserve. Local produce, sourdough from the Anglesea baker, pastries, the Blackman''s coffee van, honey, plants and seasonal fruit and veg. Go before 10am for the best bread selection. One of the most reliable Saturday morning rituals on the Surf Coast.', null, 'https://www.surfcoast.vic.gov.au/', '{"dry-ground"}', 'high', 'Research', true),
  (6, 'Belmont Sunday Market', 'market', date '2026-08-23', null, '7am–12pm', 'weekly', 'Barwon Heads Rd carpark', 'Belmont (Geelong)', 22, 'Free', '{"all-ages"}', null, null, 'Geelong''s unofficial trash-and-treasure market fills the giant Barwon Heads Rd carpark every Sunday. Stalls, food trucks, people selling from car boots. The odds of a genuine bargain are higher here than the formal vintage warehouses, though you''ll wade through some ''90s DVDs to find them. Gold coin entry, multiple food options on site. Good early-morning outing.', null, 'https://www.google.com/maps/search/Belmont+Sunday+Market+Geelong+Victoria', '{"dry-ground"}', 'high', 'Research', true),
  (7, 'Surf Coast Arts Trail', 'festival', date '2027-08-07', date '2026-10-12', '10am–4pm', 'annual', 'Various venues – Surf Coast', 'Surf Coast', 5, 'Free', '{"adults","teens"}', null, null, 'An annual open studio weekend across the Surf Coast where local artists open their homes and studios to visitors. Self-guided trail through Torquay, Anglesea, Aireys Inlet, Lorne and surrounds. A rare chance to meet artists in their working spaces and buy directly. Dates are usually the second weekend in October — verify with Surf Coast Arts Inc before going.  [Sourced Aug 2026: the 2026 trail ran 1–2 August, not October. Runs the first weekend of August; 2027 date estimated from that pattern — confirm at surfcoastartstrail.com.au.]', null, 'https://www.surfcoastarts.com/', '{"any-weather"}', 'low', 'Research', true),
  (8, 'Anglesea Family Carnival', 'community', date '2027-01-15', date '2026-01-15', '10am–4pm', 'annual', 'Anglesea Main Beach / Reserve', 'Anglesea', 15, 'Free', '{"all-ages"}', null, null, 'Annual summer carnival at Anglesea beach reserve. Free entry, stalls, food trucks, live entertainment, kids activities, sand sculpture competitions. Community run and reliably good fun for families. Usually mid-January — verify dates with Anglesea Community House.', null, 'https://www.anglesea.org.au/', '{"warm"}', 'medium', 'Research', true),
  (9, 'Lorne Pier to Pub Swim', 'sport-event', date '2027-01-10', null, 'starts 8am', 'annual', 'Lorne Pier / Front Beach', 'Lorne', 30, 'Cheap', '{"adults","teens"}', null, null, 'The world''s largest open water swimming event — around 5,000 swimmers racing 1.2km from the pier to the beach in Lorne. A genuine spectacle even if you''re just watching from the beach. The post-swim atmosphere on Lorne foreshore is brilliant. Registration required to swim; free to watch.', 'https://www.lopiswim.com.au/', 'https://www.lopiswim.com.au/', '{"calm-sea"}', 'medium', 'Research', true),
  (10, 'Anglesea Music Festival', 'festival', date '2027-03-07', date '2026-03-08', 'all day', 'annual', 'Anglesea Surf Life Saving Club', 'Anglesea', 15, 'Moderate', '{"adults","teens"}', 'Various local and regional acts', 'folk, roots, rock, pop', 'An intimate community music festival at Anglesea. Multiple stages, local food and market stalls, family friendly but predominantly adult crowd. Strong local artist focus with some regional and interstate headline acts. One of the better small festivals in the region.', 'https://www.angleseamusicfestival.com.au/', 'https://www.angleseamusicfestival.com.au/', '{"warm"}', 'medium', 'Research', true),
  (11, 'Full Moon Bonfire – Jan Juc Beach', 'night', date '2026-08-28', null, 'from sunset', 'monthly', 'Jan Juc Main Beach', 'Jan Juc', 0, 'Free', '{"all-ages"}', null, null, 'Informal community gather around a bonfire on Jan Juc beach on or near the full moon. Not an organised event — no website, no tickets — but a well-known local tradition. Bring your own drinks and something to sit on. Often 20–50 people. Check fire ban status before going — no bonfires on Total Fire Ban days.  [Next full moon over Melbourne is 28 Aug 2026 (timeanddate.com / mooninfo.org).]', null, 'https://www.google.com/maps/search/Jan+Juc+Main+Beach+Victoria', '{"no-fire-ban","full-moon"}', 'high', 'Research', true),
  (12, 'Surf Coast Walk Festival', 'festival', date '2027-05-02', date '2026-05-04', 'various walks all day', 'annual', 'Various – Surf Coast Walk', 'Torquay to Aireys', 0, 'Free', '{"all-ages"}', null, null, 'Annual celebration of the Surf Coast Walk with guided walks, coastal talks, nature activities and community events along the 44km trail from Torquay to Aireys Inlet. A mix of easy and challenging walks with local naturalists and historians as guides. Excellent for getting kids engaged with the coastline. Free, but some guided walks may require registration.', null, 'https://www.surfcoastwalk.com.au/', '{"dry-ground"}', 'medium', 'Research', true),
  (13, 'Open Mic Night – Torquay Hotel', 'gig', date '2026-08-27', null, '7pm–10pm', 'weekly', 'Torquay Hotel', 'Torquay', 4, 'Free', '{"adults","teens"}', 'Various local acts', 'mixed, folk, rock, pop', 'Weekly open mic at the Torquay Hotel. Rotating cast of local musicians, singer-songwriters and occasional surprise guests. Relaxed atmosphere, pub meals available. A genuine community night — the regulars are welcoming and the quality is usually surprisingly good.', null, 'https://www.google.com/maps/search/Torquay+Hotel+Victoria', '{"good-in-rain"}', 'high', 'Research', true),
  (14, 'Geelong After Dark – Night Markets', 'market', date '2026-11-07', null, '5pm–10pm', 'monthly', 'Johnstone Park, Geelong', 'Geelong CBD', 18, 'Free', '{"all-ages"}', null, null, 'Monthly night market in Johnstone Park in central Geelong. Food trucks, artisan stalls, live music and entertainment. Well-attended, family friendly, strong food and drink offering. Usually first Friday of summer months — verify dates on City of Greater Geelong events page.', null, 'https://www.geelongaustralia.com.au/events/', '{"warm"}', 'medium', 'Research', true),
  (15, 'Lorne Falls Festival (Spectate)', 'festival', date '2026-12-28', date '2026-12-31', 'all day / overnight', 'annual', 'Lorne Foreshore & Erskine Falls', 'Lorne', 30, 'Free to watch from town', '{"adults","teens"}', 'National headline acts', 'electronic, rock, pop, folk', 'One of Australia''s most beloved summer music festivals set on the Lorne foreshore. Headline acts across multiple stages for four nights over New Year''s. Tickets required to enter the festival grounds, but the spectacle is visible and audible from much of Lorne — the atmosphere in town is brilliant even without a ticket. If you want to attend properly, book accommodation and tickets many months out.', 'https://www.fallsfestival.com/', 'https://www.fallsfestival.com/', '{"warm"}', 'medium', 'Research', true),
  (16, 'Torquay Library – School Holiday Program', 'workshop', date '2026-09-21', date '2026-04-24', 'Sept–Oct holidays, 19 Sept – 4 Oct', 'annual', 'Torquay Library', 'Torquay', 4, 'Free', '{"kids"}', null, null, 'The Torquay Library runs free activities for kids during every school holiday period — craft, STEM activities, storytelling, author visits and themed programs. Always worth checking what''s on. Booking usually required as sessions fill fast. Check the Surf Coast Shire library events page for current program.  [Vic Term 3 ends 18 Sept 2026, Term 4 starts 5 Oct (education.vic.gov.au). Program days within the holidays vary — check the library.]', null, 'https://www.surfcoastshire.vic.gov.au/leisure-and-environment/libraries', '{"good-in-rain"}', 'medium', 'Research', true),
  (17, 'Anglesea Community House – Ceramics', 'workshop', date '2026-08-26', date '2026-06-17', '10am–12pm Wednesdays', 'weekly', 'Anglesea Community House', 'Anglesea', 15, 'Cheap', '{"adults"}', null, null, '10-week term ceramics class at Anglesea Community House. Beginners welcome. Covers hand-building techniques, glazing and kiln firing. Classes fill quickly — enrol at the start of term. Anglesea Community House also runs yoga, art, language and wellness classes — check the full term program at anglesea.org.au.', 'https://www.anglesea.org.au/', 'https://www.anglesea.org.au/', '{"good-in-rain"}', 'high', 'Research', true),
  (18, 'Eta Aquarid Meteor Shower', 'night', date '2027-05-05', date '2026-05-07', 'midnight–4am', 'annual', 'Bells Beach Cliff / Jan Juc', 'Jan Juc', 2, 'Free', '{"all-ages"}', null, null, 'The Eta Aquarid meteor shower — the best annual meteor shower visible from the southern hemisphere — peaks around May 5–7 each year. Produced by debris from Halley''s Comet, the shower can produce 30–50 meteors per hour at peak from the southern hemisphere, significantly better than from the north. Head to Bells Beach cliff or the Jan Juc clifftops after midnight. Best after 2am when the radiant is highest. New moon in 2026 means ideal viewing conditions — no moonlight competition.', null, 'https://www.timeanddate.com/astronomy/meteor-shower/', '{"clear-sky","low-wind","new-moon"}', 'high', 'Research', true),
  (19, 'Dawn Service – Torquay RSL', 'community', date '2027-04-25', null, '6am', 'annual', 'Torquay Cenotaph', 'Torquay', 4, 'Free', '{"all-ages"}', null, null, 'ANZAC Day dawn service at the Torquay cenotaph. Attended by hundreds of locals each year. Wreath-laying, Last Post, a minute''s silence. A quiet, dignified community gathering — arrive 15 minutes early. The march follows later in the morning through central Torquay.', null, 'https://www.google.com/maps/search/Torquay+Cenotaph+Victoria', '{"any-weather"}', 'high', 'Research', true),
  (20, 'Live Music – The Sound Doctor', 'gig', date '2026-08-28', null, '8pm–11pm', 'weekly', 'The Sound Doctor', 'Torquay', 4, 'Free', '{"adults","teens"}', 'Local & regional acts', 'rock, electronic, indie, pop', 'Torquay''s dedicated live music venue. Friday and Saturday nights, occasionally Thursdays. Mix of local originals acts, tribute bands and regional touring artists. Intimate venue — good sound, attentive staff. Probably the Surf Coast venue most likely to host acts you haven''t heard of yet.', null, 'https://www.facebook.com/thesounddoctor/', '{"good-in-rain"}', 'high', 'Research', true),
  (21, 'Anglesea Community Market', 'market', date '2026-09-13', null, '9am–1pm', 'monthly', 'Anglesea Surf Life Saving Club', 'Anglesea', 15, 'Free', '{"all-ages"}', null, null, 'Monthly community market at the Anglesea SLSC. Local produce, crafts, clothing, food stalls and bric-a-brac. A smaller, friendlier version of the Torquay Farmers Market — good for picking up local art, plants and handmade things. Usually second Sunday of the month — verify with Anglesea Community House.', null, 'https://www.anglesea.org.au/', '{"dry-ground"}', 'high', 'Research', true),
  (22, 'Surf Industry Sample Sales – Baines Crescent', 'market', date '2026-12-26', date '2027-01-06', '10am–5pm', 'annual', 'Baines Crescent outlets', 'Torquay', 4, 'Free', '{"all-ages"}', null, null, 'The Rip Curl, Billabong, Quiksilver and other surf brand clearance stores on Baines Crescent run their biggest discounts over the summer holiday period, typically Boxing Day through early January. Not exactly a vintage market but excellent value for surf gear, wetsuits and apparel. Combine with a visit to Garage Torquay on the same street.', null, 'https://www.google.com/maps/search/Baines+Crescent+Torquay+Victoria', '{"good-in-rain"}', 'medium', 'Research', true),
  (23, 'Lorne Schoolies Week (be aware)', 'community', date '2026-11-20', date '2026-11-28', 'all hours', 'annual', 'Lorne Foreshore', 'Lorne', 30, 'N/A', '{"adults"}', null, null, 'Lorne becomes the destination for thousands of Victorian Year 12 school leavers celebrating the end of the school year for about 10 days in late November. The town is extremely busy, accommodation books out entirely, and the foreshore atmosphere is not well-suited to families with young kids. Useful to know: avoid Lorne during this period if you''re looking for a relaxed family outing. Plan around it rather than into it.', null, 'https://www.google.com/maps/search/Lorne+Victoria', '{"any-weather"}', 'medium', 'Research', true),
  (24, 'Winter Solstice Gathering – Bells Beach', 'community', date '2027-06-21', null, 'sunset', 'annual', 'Bells Beach Cliff', 'Bells Beach', 3, 'Free', '{"all-ages"}', null, null, 'An informal community gather on the Bells Beach cliff for the winter solstice sunset — the shortest day of the year. Not an organised event but a well-known local tradition. Usually 30–80 people arrive around sunset with warm drinks, rugs and sometimes guitars. The solstice sunset from the south-facing cliff is atmospheric even in cold weather.', null, 'https://www.google.com/maps/search/Bells+Beach+Torquay+Victoria', '{"clear-sky"}', 'high', 'Research', true),
  (25, 'Great Ocean Road Running Festival', 'sport-event', date '2027-05-16', date '2026-05-17', 'from 7am', 'annual', 'Lorne Foreshore / Great Ocean Road', 'Lorne', 30, 'Moderate', '{"adults","teens"}', null, null, 'A weekend running festival along the Great Ocean Road centred on Lorne, with events from 1km kids runs to half marathon and marathon distances. The marathon route along the Great Ocean Road is one of the most scenic in Australia. Even non-runners find it worth heading to Lorne to watch the finishes on the foreshore. Book accommodation months out if you want to stay overnight.', 'https://www.greatoceanroadrunningfestival.com.au/', 'https://www.greatoceanroadrunningfestival.com.au/', '{"any-weather"}', 'medium', 'Research', true),
  (26, 'Torquay Cowrie Market', 'market', date '2026-09-20', null, '9am–2pm', 'monthly', 'Elephant Walk, Torquay', 'Torquay', 4, 'Free', '{"all-ages"}', null, null, 'Surf Coast Arts Inc. craft and art market on the third Sunday of the month, September through April. 2026–27 season dates: 20 Sep, 18 Oct, 15 Nov, 20 Dec, 17 Jan, 21 Feb, 21 Mar, 18 Apr.', null, 'https://www.torquaycowriemarket.com/', '{"warm","dry-ground"}', 'high', 'Research', true),
  (27, 'Bells Beach Surf Film Festival', 'festival', date '2027-01-06', null, 'evening sessions', 'annual', 'Australian National Surfing Museum', 'Torquay', 4, 'Cheap', '{"teens","adults"}', null, null, 'Three nights of surf films at the surfing museum. Held in the first week of January; the 2026 festival has finished and the site says ''see you again in 2027''. Exact 2027 dates not yet published.', null, 'https://www.bellsbeachsurffilmfestival.com/', '{"any-weather"}', 'low', 'Research', true),
  (28, 'Deans Marsh Festival', 'festival', date '2027-03-21', null, '10am–3pm', 'annual', 'Deans Marsh Memorial Reserve', 'Deans Marsh', 40, 'Free', '{"all-ages"}', null, null, 'Country community festival held at the end of March every year since 1994. The 2025 festival ran Sunday 22 March, 10am–3pm; the 2027 date is estimated from that pattern.', null, 'https://www.deansmarshcottage.org.au/deans-marsh-festival', '{"warm","dry-ground"}', 'low', 'Research', true),
  (29, 'Geelong Pride Film Festival', 'festival', date '2027-05-05', null, 'various sessions', 'annual', 'Venues across Geelong', 'Geelong', 21, 'Cheap', '{"teens","adults"}', null, null, 'One of the largest regional LGBTQIA+ film festivals in Australia. The 2026 festival ran until Sunday 10 May; the 2027 date is estimated from that.', null, 'https://www.gpff.ferve.tickets/', '{"good-in-rain"}', 'low', 'Research', true),
  (30, 'ANGAIR Wildflower & Art Weekend', 'festival', date '2026-09-19', null, 'Sat & Sun', 'annual', 'Anglesea Community Hub, McMillan St', 'Anglesea', 20, 'Cheap', '{"all-ages"}', null, null, 'CONFIRMED for 19–20 September 2026 at the Anglesea Community Hub. Spectacular display of local wildflowers alongside an art show — one of the best weekends on the Surf Coast calendar.', null, 'https://angair.org.au/angair-wildflower-arts-show-2026/', '{"warm","dry-ground"}', 'high', 'Research', true),
  (31, 'One Planet Festival – Ocean Grove', 'festival', date '2027-03-27', null, '11am–5pm', 'annual', 'Ocean Grove Park & Pavilion', 'Ocean Grove', 38, 'Free', '{"all-ages"}', null, null, 'Community-led sustainability festival run by local volunteers. The 2026 festival ran 28 March, 11am–5pm; the 2027 date is estimated from that.', null, 'https://www.oneplanetfest.com.au/', '{"warm","dry-ground"}', 'low', 'Research', true)
